  const save=async(draft:any)=>{try{setError('');await runOperationalAdmin(state,'admin_upsert',{entity:'challenge_card',record:{...draft,team_id:draft.team_id||selected?.id,session_id:draft.session_id||selected?.sheetSessionId}})}catch(err:any){setError(err?.message||'No fue posible guardar la Tarjeta Reto.')}};
  return <div className="page charter-repository"><div className="page-heading"><div><p className="eyebrow violet">REPOSITORIO</p><h2>Tarjetas Reto</h2><p>Consulta y administra las Tarjetas Reto construidas por los equipos.</p></div>{teams.length>0&&<span className="repository-count">{teams.length} tarjetas · {teams.length} equipos · {clusterCount} clústeres</span>}</div>{teams.length?<><nav className="share-selector repository-selector">{teams.map((team:any,i:number)=><button key={team.id} className={team.id===selected?.id?'active':''} onClick={()=>{setSelectedId(team.id);setExpanded(false);setEditing(false)}}><span>{String(i+1).padStart(2,'0')}</span><b>{charterFor(state,team).name||'Tarjeta Reto pendiente'}</b><small>{team.name}</small></button>)}</nav><div className="charter-repository-current"><RetoFicha state={state} team={selected} showCluster expanded={expanded} onToggle={()=>setExpanded(!expanded)}/><div className="admin-actions repository-actions"><button className="secondary data-action" onClick={()=>setExpanded(!expanded)}>Ver ficha</button><button className="secondary data-action" onClick={()=>setEditing(!editing)}>Editar</button><button className="secondary data-action danger" onClick={remove}>Eliminar</button></div>{editing&&<AdminEditor kind="challenge_card" record={card} state={state} onCancel={()=>setEditing(false)} onSave={save}/>} {error&&<p className="admin-error" role="alert">{error}</p>}</div></>:<div className="empty large">Aún no hay Tarjetas Reto disponibles.</div>}</div>
