const labDataTabs=[['participants','Participantes'],['prompts','Aprende a pedir'],['challenges','Retos'],['clusters','Clusters'],['teams','Equipos'],['cards','Tarjetas Reto']] as const;
const dataText=(value:any)=>value===undefined||value===null||value===''?'—':Array.isArray(value)?value.join(' · '):String(value);
const dataLabels:Record<string,string>={
  session_id:'Sesión',participant_id:'Participante',team_id:'Equipo',cluster_id:'Clúster',challenge_id:'Reto',card_id:'Tarjeta Reto',record_id:'Registro',
  title:'Nombre',name:'Nombre',context:'Tarea / contexto',friction:'Qué lo hace difícil',impact:'Impacto',problem:'Problema a resolver',
  pov:'POV / problema validado',hmw:'Pregunta reto',pregunta_reto:'Pregunta reto',challenge_ids:'Retos asociados',participant_ids:'Participantes',
  visible_id:'ID visible',status:'Estado',card_status:'Estado de Tarjeta Reto',created_at:'Creado',updated_at:'Actualizado',
  role_ai:'Rol de la IA',role_human:'Rol humano',mvp:'MVP',success_indicator:'Indicador de éxito'
};
const dataLabel=(key:string)=>dataLabels[key]||key.replace(/_/g,' ').replace(/\b\w/g,letter=>letter.toUpperCase());
async function runOperationalAdmin(state:any,operation:string,data:any){
  const response=await fetch('/api/lab/admin',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({cohort:state.executionId||'piloto-gestion-humana',operation,data})});
  const result=await response.json().catch(()=>null);
  if(!response.ok)throw new Error(result?.error||'No fue posible actualizar la base operativa.');
  window.location.reload();
}
function DataTable({headers,children}:any){return <div className="data-table-wrap"><table className="data-table"><thead><tr>{headers.map((head:string)=><th key={head}>{head}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}
function CompleteStoredCard({state,team,row}:any){const raw=Object.entries(row||team?.sheetCard||{});return <section className="data-card-detail">{team?<RetoFicha state={state} team={team} expanded showCluster/>:<p className="empty">La tarjeta está almacenada, pero el equipo asociado aún no está disponible en la sesión.</p>}{raw.length>0&&<section className="data-raw-card"><h3>Datos completos almacenados</h3><div>{raw.map(([key,value])=><p key={key}><b>{dataLabel(key)}</b><span>{dataText(value)}</span></p>)}</div></section>}</section>}
function AdminEditor({kind,record,state,onCancel,onSave}:any){
  const [draft,setDraft]=useState<any>(()=>structuredClone(record));
  const technical=new Set(['session_id','created_at','updated_at','confirmed_at','record_id','card_id','challenge_id','cluster_id','team_id','participant_id','visible_id']);
  const labels:any={challenge:'Reto',cluster:'Clúster',team:'Equipo',challenge_card:'Tarjeta Reto'};
  const update=(key:string,value:any)=>setDraft((old:any)=>({...old,[key]:value}));
  const fields=Object.entries(draft).filter(([key])=>!technical.has(key));
  return <section className="admin-editor"><header><div><p className="eyebrow violet">EDICIÓN · {labels[kind]}</p><h3>{kind==='challenge_card'?'Editar Tarjeta Reto':`Editar ${labels[kind]}`}</h3></div><button className="secondary data-action" onClick={onCancel}>Cerrar</button></header>{kind==='team'&&<p className="admin-note"><b>{draft.name||'Equipo'}</b> · ID visible {draft.visible_id||'—'}. El identificador técnico permanece protegido.</p>}{kind==='cluster'&&<label className="admin-field"><span>Retos asociados</span><div className="admin-checks">{(state.opportunities||[]).map((item:any)=><label key={item.id}><input type="checkbox" checked={(draft.challenge_ids||[]).includes(item.id)} onChange={event=>update('challenge_ids',event.target.checked?[...(draft.challenge_ids||[]),item.id]:(draft.challenge_ids||[]).filter((id:string)=>id!==item.id))}/>{item.title||'Reto sin título'}</label>)}</div></label>}{kind==='team'&&<><label className="admin-field"><span>Clúster asociado</span><select value={draft.cluster_id||''} onChange={event=>update('cluster_id',event.target.value)}><option value="">Sin clúster</option>{(state.clusters||[]).map((item:any)=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="admin-field"><span>Participantes</span><div className="admin-checks">{(state.participants||[]).map((item:any)=>{const selected=(draft.participant_ids||[]).some((person:any)=>(typeof person==='string'?person:person.email||person.id)===(item.email||item.id));return <label key={item.email||item.id}><input type="checkbox" checked={selected} onChange={event=>{const people=(draft.participant_ids||[]).filter((person:any)=>(typeof person==='string'?person:person.email||person.id)!==(item.email||item.id));update('participant_ids',event.target.checked?[...people,{name:item.name||'',email:item.email||'',id:item.id||item.email||''}]:people)}}/>{item.name||item.email}</label>})}</div></label></>}{kind==='challenge_card'&&<label className="admin-field"><span>Equipo</span><select value={draft.team_id||''} onChange={event=>update('team_id',event.target.value)}>{(state.teams||[]).map((item:any)=><option key={item.id} value={item.id}>{item.name} · ID {visibleTeamId(item)}</option>)}</select></label>}<div className="admin-form">{fields.filter(([key])=>!['challenge_ids','participant_ids'].includes(key)).map(([key,value]:any)=><label className="admin-field" key={key}><span>{dataLabel(key)}</span>{key==='status'?<select value={value||''} onChange={event=>update(key,event.target.value)}><option value="">Sin estado</option><option value="EN_REVISION">En revisión</option><option value="VALIDADO">Validado</option><option value="confirmed">Confirmada</option><option value="draft">En construcción</option><option value="not_started">No iniciada</option></select>:<textarea value={typeof value==='object'?JSON.stringify(value):value||''} onChange={event=>update(key,event.target.value)}/>}</label>)}</div><footer><button className="secondary" onClick={onCancel}>Cancelar</button><button className="primary" onClick={()=>onSave(draft)}><Save size={15}/>Guardar cambios</button></footer></section>}
function LabData({state,onAdmin}:any){
  const admin=onAdmin||(async(operation:string,data:any)=>{const response=await fetch('/api/lab/admin',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({cohort:state.executionId||'piloto-gestion-humana',operation,data})});if(!response.ok){const result=await response.json().catch(()=>null);throw new Error(result?.error||'No se pudo actualizar la base operativa.')}window.location.reload();return true;});
  const [tab,setTab]=useState<typeof labDataTabs[number][0]>('participants'),[query,setQuery]=useState(''),[category,setCategory]=useState('Todas'),[status,setStatus]=useState('Todos'),[selected,setSelected]=useState<any>(null),[editing,setEditing]=useState<any>(null),[notice,setNotice]=useState('');
  const teams=state.teams||[], opportunities=state.opportunities||[], clusters=state.clusters||[], prompts=state.promptExerciseResults||[], rawCards=state.sheetChallengeCards||[];
  const participants=Array.from(new Map([...(state.participants||[]),...teams.flatMap((team:any)=>(team.members||[]).map((member:any)=>({...member,team:team.name})))].map((person:any)=>[person.email||person.id||person.name,{...person}])).values());
  const cards=(rawCards.length?rawCards:teams.filter((team:any)=>Object.keys(team.charter||{}).length).map((team:any)=>team.sheetCard||{team_id:team.id,status:team.stage,...team.charter})).map((row:any)=>{const team=teams.find((item:any)=>item.id===(row.team_id||row.teamId)),card=team?charterFor(state,team):row;return {row,team,teamName:team?.name||row.team||row.equipo||'Equipo por definir',name:card.name||row.titulo||'Tarjeta Reto pendiente',cluster:card.cluster||row.cluster||'—',status:row.status||team?.stage||'Pendiente',participants:card.participants||(team?.members||[]).map((member:any)=>member.name).join(' · ')||'—'}});
  const matches=(values:any[])=>!query.trim()||values.some(value=>dataText(value).toLowerCase().includes(query.trim().toLowerCase()));
  const categories=['Pieza gráfica','Presentación','Documento','Gráfica'];
  const filteredPrompts=prompts.filter((item:any)=>(category==='Todas'||item.category===category)&&matches([item.participantId,item.category,item.status,item.promptFinal]));
  const filteredCards=cards.filter((card:any)=>(status==='Todos'||card.status===status)&&matches([card.teamName,card.name,card.cluster,card.status,card.participants]));
  const remove=async(kind:string,row:any,message:string)=>{if(!window.confirm(message))return;try{setNotice('');await admin('admin_delete',{entity:kind,id:row[kind==='challenge'?'challenge_id':kind==='cluster'?'cluster_id':kind==='team'?'team_id':'card_id'],session_id:row.session_id||row.sheetSessionId});setSelected(null);setEditing(null)}catch(error:any){setNotice(error?.message||'No fue posible eliminar el registro.')}};
  const save=async(kind:string,draft:any)=>{try{setNotice('');await admin('admin_upsert',{entity:kind,record:{...draft,session_id:draft.session_id||draft.sheetSessionId}});setEditing(null)}catch(error:any){setNotice(error?.message||'No fue posible guardar los cambios.')}};
  return <section className="page lab-data"><div className="page-heading"><div><p className="eyebrow violet">ADMINISTRACIÓN · BASE OPERATIVA</p><h2>Datos del LAB</h2><p>Consulta y administración de la información sincronizada con la base operativa.</p></div><a className="secondary" href={state.labDatabaseUrl} target="_blank" rel="noreferrer"><ExternalLink size={16}/>Abrir base de datos en Google Sheets ↗</a></div><nav className="lab-data-tabs">{labDataTabs.map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>{setTab(id);setSelected(null);setEditing(null)}}>{label}</button>)}</nav><div className="data-toolbar"><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar en los datos…"/>{tab==='prompts'&&<select value={category} onChange={event=>setCategory(event.target.value)}><option>Todas</option>{categories.map(item=><option key={item}>{item}</option>)}</select>}{tab==='cards'&&<select value={status} onChange={event=>setStatus(event.target.value)}><option>Todos</option>{Array.from(new Set(cards.map((card:any)=>card.status))).map((item:any)=><option key={item}>{item}</option>)}</select>}</div>
  {tab==='participants'&&<><div className="data-summary"><article><b>{participants.length}</b><span>participantes</span></article><article><b>{teams.length}</b><span>equipos</span></article><article><b>{opportunities.length}</b><span>retos registrados</span></article></div><DataTable headers={['Participante','Correo','Equipo','Estado']}>{participants.filter((person:any)=>matches([person.name,person.email,person.team])).map((person:any,index:number)=><tr key={person.email||person.id||index}><td>{person.name||'Sin nombre'}</td><td>{person.email||'—'}</td><td>{person.team||teams.find((team:any)=>(team.members||[]).some((member:any)=>member.email===person.email))?.name||'Sin equipo'}</td><td>{person.status||'Activo'}</td></tr>)}</DataTable></>}
  {tab==='prompts'&&<><div className="data-summary prompt-summary">{categories.map(item=><article key={item}><b>{new Set(prompts.filter((prompt:any)=>prompt.category===item).map((prompt:any)=>prompt.participantId)).size}</b><span>{item}</span></article>)}</div><DataTable headers={['Participante','Categoría','Estado','Resultado / prompt registrado']}>{filteredPrompts.map((item:any,index:number)=><tr key={item.recordId||index}><td>{participants.find((person:any)=>person.id===item.participantId||person.email===item.participantId)?.name||item.participantId||'—'}</td><td>{item.category||'—'}</td><td>{item.status||'—'}</td><td className="data-long">{item.promptFinal||'—'}</td></tr>)}</DataTable>{!filteredPrompts.length&&<p className="empty">Aún no hay respuestas registradas para este filtro.</p>}</>}
  {tab==='challenges'&&<DataTable headers={['Reto','Tarea / contexto','Dificultad','Impacto','Estado','']}>{opportunities.filter((item:any)=>matches([item.title,item.context,item.friction,item.problem,item.radar])).map((item:any)=><tr key={item.id}><td><b>{item.title||'Sin título'}</b><small>{item.radar||'Sin categoría'}</small></td><td>{item.context||'—'}</td><td>{item.friction||'—'}</td><td>{item.problem||'—'}</td><td>{item.status||'Registrado'}</td><td className="admin-actions"><button className="secondary data-action" onClick={()=>setSelected({kind:'challenge',row:item})}>Ver</button><button className="secondary data-action" onClick={()=>setEditing({kind:'challenge',record:{session_id:item.sheetSessionId,challenge_id:item.id,title:item.title,context:item.context,friction:item.friction,impact:item.problem,status:item.status}})}>Editar</button><button className="secondary data-action danger" onClick={()=>remove('challenge',{challenge_id:item.id,sheetSessionId:item.sheetSessionId},'¿Eliminar este reto de la base operativa?')}>Eliminar</button></td></tr>)}</DataTable>}
  {tab==='clusters'&&<DataTable headers={['Clúster','Retos','POV','Pregunta reto','Estado','']}>{clusters.filter((cluster:any)=>matches([cluster.name,cluster.pov,cluster.hmw,cluster.status])).map((cluster:any)=>{const linked=teams.filter((team:any)=>team.clusterId===cluster.id).length;return <tr key={cluster.id}><td><b>{cluster.name||'Sin nombre'}</b></td><td>{(cluster.opportunityIds||[]).length}</td><td className="data-long">{cluster.pov||'—'}</td><td className="data-long">{cluster.hmw||'—'}</td><td>{cluster.status==='VALIDADO'?'Clúster validado':cluster.status||'En revisión'}</td><td className="admin-actions"><button className="secondary data-action" onClick={()=>setSelected({kind:'cluster',row:cluster})}>Ver</button><button className="secondary data-action" onClick={()=>setEditing({kind:'cluster',record:{session_id:cluster.sheetSessionId,cluster_id:cluster.id,name:cluster.name,pov:cluster.pov,pregunta_reto:cluster.hmw,status:cluster.status,challenge_ids:cluster.opportunityIds||[]}})}>Editar</button><button className="secondary data-action" onClick={()=>save('cluster',{session_id:cluster.sheetSessionId,cluster_id:cluster.id,name:cluster.name,pov:cluster.pov,pregunta_reto:cluster.hmw,status:'EN_REVISION',challenge_ids:cluster.opportunityIds||[]})}>Reabrir</button><button className="secondary data-action danger" onClick={()=>remove('cluster',{cluster_id:cluster.id,sheetSessionId:cluster.sheetSessionId},`¿Eliminar este clúster? Tiene ${(cluster.opportunityIds||[]).length} retos y ${linked} equipos asociados.`)}>Eliminar</button></td></tr>})}</DataTable>}
  {tab==='teams'&&<DataTable headers={['Equipo','ID visible','Clúster / reto','Participantes','Tarjeta Reto','Estado','']}>{teams.filter((team:any)=>matches([team.name,team.visibleId,team.stage,team.clusterId,(team.members||[]).map((member:any)=>member.name)])).map((team:any)=>{const cluster=clusters.find((item:any)=>item.id===team.clusterId),cardState=teamCardStatus(team);return <tr key={team.id}><td><b>{team.name}</b></td><td>ID {visibleTeamId(team)}</td><td>{cluster?.name||'—'}</td><td>{(team.members||[]).map((member:any)=>member.name).join(' · ')||'—'}</td><td>{cardState==='confirmed'?'Confirmada':cardState==='in_progress'?'En construcción':'No iniciada'}</td><td>{team.stage||'En formación'}</td><td className="admin-actions"><button className="secondary data-action" onClick={()=>setSelected({kind:'team',row:team})}>Ver</button><button className="secondary data-action" onClick={()=>setEditing({kind:'team',record:{session_id:team.sheetSessionId,team_id:team.id,name:team.name,visible_id:team.visibleId,cluster_id:team.clusterId,challenge_id:team.challengeId,capacity:team.capacity,status:team.stage,participant_ids:team.members||[],card_status:team.cardStatus}})}>Editar</button><button className="secondary data-action danger" onClick={()=>remove('team',{team_id:team.id,sheetSessionId:team.sheetSessionId},'¿Eliminar este equipo de la base operativa?')}>Eliminar</button></td></tr>})}</DataTable>}
  {tab==='cards'&&<><DataTable headers={['Equipo','Nombre del reto','Clúster','Estado','Participantes','']}>{filteredCards.map((card:any,index:number)=><tr key={card.row.card_id||card.row.team_id||index}><td>{card.teamName}</td><td><b>{card.name}</b></td><td>{card.cluster}</td><td>{card.status}</td><td>{card.participants}</td><td className="admin-actions"><button className="secondary data-action" onClick={()=>setSelected({kind:'challenge_card',...card})}>Ver ficha</button><button className="secondary data-action" onClick={()=>setEditing({kind:'challenge_card',record:{...card.row,session_id:card.row.session_id||card.team?.sheetSessionId,team_id:card.row.team_id||card.team?.id}})}>Editar</button><button className="secondary data-action danger" onClick={()=>remove('challenge_card',card.row,'¿Eliminar esta Tarjeta Reto de la base operativa?')}>Eliminar</button><button className="secondary data-action" onClick={async()=>{if(!window.confirm('¿Restablecer esta Tarjeta Reto y dejar el equipo pendiente?'))return;try{setNotice('');await admin('admin_reset_card',{session_id:card.row.session_id||card.team?.sheetSessionId,card_id:card.row.card_id,team_id:card.row.team_id||card.team?.id})}catch(error:any){setNotice(error?.message||'No fue posible restablecer la Tarjeta Reto.')}}}>Restablecer</button></td></tr>)}</DataTable>{!filteredCards.length&&<p className="empty">Aún no hay Tarjetas Reto registradas para este filtro.</p>}{selected?.kind==='challenge_card'&&<CompleteStoredCard state={state} team={selected.team} row={selected.row}/>}</>}
  {selected&&selected.kind!=='challenge_card'&&<section className="data-card-detail"><section className="data-raw-card"><header><h3>Detalle</h3><button className="secondary data-action" onClick={()=>setSelected(null)}>Cerrar</button></header><div>{Object.entries(selected.row).map(([key,value])=><p key={key}><b>{dataLabel(key)}</b><span>{dataText(value)}</span></p>)}</div></section></section>}{editing&&<AdminEditor kind={editing.kind} record={editing.record} state={state} onCancel={()=>setEditing(null)} onSave={(draft:any)=>save(editing.kind,draft)}/>}
  {notice&&<p className="admin-error" role="alert">{notice}</p>}</section>
}

function RetoPresentation({state,patch,onNext}:any){
  const step=Math.max(0,Math.min(1,state.retoStep||0)),teams=(state.teams||[]).filter((t:any)=>state.clusters.some((c:any)=>c.id===t.clusterId&&c.status==='VALIDADO')),team=teams[0],cta=ctaFor(state,'land',teamAssistantContext(state,team)),questions=['¿Cómo lo hacen hoy?','¿Dónde está la dificultad?','¿Con qué cuentan?','¿Qué sabe hacer el equipo?','¿Qué ideas tienen?'],go=(n:number)=>patch((d:any)=>d.retoStep=Math.max(0,Math.min(1,n)),'Subsección de Tarjetas Reto actualizada');
  return <article className="reto-presentation"><p className="eyebrow violet">MOMENTO 11 · TARJETAS RETO</p><div className="reto-present-tabs">{retoSteps.map((s:any,i:number)=><button key={s.id} className={i===step?'active':''} onClick={()=>go(i)}>{i+1} · {s.name}</button>)}</div><h1>{step===0?'Conversen y analicen':'Estructuren su Tarjeta Reto con el GPT'}</h1><p className="reto-present-subtitle">{step===0?'Analicen el reto antes de estructurar la Tarjeta Reto.':'Ahora utilizarán el Asistente del LAB para convertir lo que conversaron en una Tarjeta Reto clara, viable y medible.'}</p>{step===0?<><div className="reto-present-questions">{questions.map(q=><div key={q}>{q}</div>)}</div><RetoContext state={state} team={team} compact/></>:<div className="reto-present-assistant reto-present-assistant-mock"><section><span className="reto-gpt-mark">◎</span><div><h3>Abre el Asistente del LAB</h3><p>Haz clic para abrir nuestro GPT en tu cuenta de ChatGPT y comienza a estructurar tu Tarjeta Reto.</p></div><CtaButton cta={cta}/><small>↗ Se abrirá en una nueva pestaña de ChatGPT.</small></section><section><h3>Antes de empezar</h3><ol><li>Un integrante lidera la conversación con el GPT.</li><li>El equipo complementa y valida.</li><li>Respondan con información real.</li><li>Revisen y ajusten la propuesta del asistente.</li></ol></section><p><b>IA como copiloto, decisión humana.</b></p></div>}<div className="reto-present-nav"><button className="secondary" disabled={step===0} onClick={()=>go(0)}>← Anterior</button>{step===0?<button className="primary" onClick={()=>go(1)}>Siguiente → Construyan la Tarjeta Reto</button>:<button className="primary" onClick={onNext}>Siguiente →</button>}</div></article>
}

type State = ReturnType<typeof template> & Record<string, any>;
type View = "home" | "configure" | "live" | "wall" | "teams" | "charter" | "data" | "solutions";
const labels: Record<View, string> = { home: "Inicio", configure: "Configurador", live: "Sesión en vivo", wall: "Muro de retos", teams: "Equipos", charter: "Tarjetas Reto", data: "Datos del LAB", solutions: "Soluciones" };
const format = (s: number) => `${String(Math.floor(Math.max(0,s)/60)).padStart(2,"0")}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,"0")}`;
const statusClass = (s:string) => s === "ABIERTA" ? "open" : s === "FINALIZADA" ? "finished" : "locked";
const participantUrl = () => typeof window === "undefined" ? "" : `${window.location.origin}${window.location.pathname}?join=1&cohort=${encodeURIComponent(new URLSearchParams(window.location.search).get("cohort")||"piloto-gestion-humana")}`;
const blockSeconds=(block:any)=>Math.max(0,Number(block?.minutes||0)*60);
const clockFor=(state:any,block:any,now=Date.now())=>{const saved=state.momentTimers?.[block?.id],base=blockSeconds(block);const remaining=saved?.remainingSeconds??base;return Math.max(0,remaining-(saved?.running?(now-(saved.started||now))/1000:0))};
const observeDefaults=[{id:'observe',name:'Observa',title:'Mira tu trabajo cotidiano.',content:'Piensa en varias tareas o situaciones reales de tu trabajo. Busca momentos donde haya esfuerzo, repetición, demoras, reprocesos o dificultad.',note:'Hazlo primero en papel. Identifica entre 3 y 5 situaciones.',items:['Repetición','Tiempo','Dificultad','Información dispersa','Esfuerzo manual','Reproceso']},{id:'choose',name:'Elige',title:'Escoge UNA situación.',content:'Elige una situación real que valga la pena entender mejor.',items:['¿Ocurre realmente?','¿Se repite?','¿Genera una fricción concreta?','¿Vale la pena entenderla mejor?']},{id:'talk',name:'Conversa',title:'Cuéntasela a otra persona.',content:'Describe la situación con detalle antes de buscar una solución.',items:['¿Qué haces exactamente?','¿Cuándo ocurre?','¿Para qué lo haces?','¿Qué hace difícil esa tarea?']},{id:'breakdown',name:'Desarma',title:'Analiza la tarea por partes.',content:'Mira la actividad paso a paso para hacer visible lo que hoy queda implícito.',items:['¿Qué haces exactamente?','¿Qué necesitas?','¿Qué obtienes?','¿Dónde está la fricción?']},{id:'reframe',name:'Reformula',title:'Convierte la situación en un reto claro.',content:'Formula una oportunidad concreta, sin asumir todavía la solución.',formula:'Cuando [situación], necesito [necesidad], para lograr [resultado], pero actualmente [fricción].',example:'Al consolidar información de distintas fuentes, necesito distinguir con rapidez los datos relevantes para elaborar el informe, pero actualmente debo revisar y organizar cada insumo de forma manual.'},{id:'register',name:'Registra / Muro Live',title:'Registra tu reto',content:'Compártelo con el grupo y observa cómo se construye el muro en tiempo real.',note:'Revisa tu tarjeta, realiza los últimos ajustes y envíala al muro.'}];
const retoSteps=[{id:'converse',name:'Conversen y analicen'},{id:'card',name:'Construyan la Tarjeta Reto'}];
const ctaDefaults:any={prompt:{text:'✨ Abrir Asistente del LAB ↗'},land:{text:'Construir Tarjeta Reto ↗'}};
const ctaFor=(state:any,blockId:string,context?:any)=>{const current={...ctaDefaults[blockId],active:true,...(state.blocks?.find((b:any)=>b.id===blockId)?.cta||{})},legacy=blockId==='land'?{...ctaDefaults.land,active:true,...(state.blocks?.find((b:any)=>b.id==='charter')?.cta||{})}:undefined,cta=current.url||current.active===false?current:(legacy?.url||legacy?.active===false?legacy:current);if(!cta.url||!context)return cta;try{const url=new URL(cta.url);url.searchParams.set('lab_context',JSON.stringify(context));return {...cta,url:url.toString()}}catch{return cta}};
function CtaButton({cta,onOpen}:any){if(!cta?.active)return null;return cta.url?<a className="primary link" target="_blank" rel="noreferrer" href={cta.url} onClick={onOpen}>{cta.text}</a>:<button className="primary" disabled>{cta?.text||'Abrir Asistente del LAB ↗'}</button>}

export default function HomePage() {
  const [state,setState]=useState<State>(template() as State),[ready,setReady]=useState(false),[view,setView]=useState<View>("home"),[showQR,setShowQR]=useState(false),[present,setPresent]=useState(false),[menuOpen,setMenuOpen]=useState(true),[now,setNow]=useState(Date.now()),[toast,setToast]=useState("");
  const isParticipant=typeof window!=="undefined"&&new URLSearchParams(window.location.search).get("join")==="1",cohort=typeof window==="undefined"?"piloto-gestion-humana":new URLSearchParams(window.location.search).get("cohort")||"piloto-gestion-humana";
async function load(silent=false){const r=await fetch(`/api/lab?cohort=${encodeURIComponent(cohort)}`,{cache:"no-store"});if(!r.ok){if(!silent)setToast("No se pudo cargar el LAB.");return;}const data=await r.json();const fresh=template();data.executionId=data.executionId||cohort;data.pulseConfig=pulseDefaults.map((base:any)=>({...base,active:data.pulseConfig?.find((q:any)=>q.id===base.id)?.active??true}));data.pulseFacilitatorStep=data.pulseFacilitatorStep||0;data.helpEnabled=data.helpEnabled??true;data.pulseFinal=data.pulseFinal??false;data.pulseView=data.pulseView||'dashboard';data.promptStep=Math.max(0,Math.min(2,data.promptStep||0));data.blocks=(data.blocks||fresh.blocks).map((b:any)=>({...b,resourceItems:b.resourceItems||[],timerEnabled:b.timerEnabled??true})).filter((b:any)=>!['frame','validate','scope'].includes(b.id));const breakBlock=data.blocks.find((b:any)=>b.id==='break');if(breakBlock){breakBlock.purpose='Pausa para volver a mirar el trabajo';breakBlock.content='Ahora nos tomaremos un break. Descansa un poco y volvemos en unos minutos.';breakBlock.methodology='Pausa logística.';}if(!data.blocks.some((b:any)=>b.id==='concepts')){const at=data.blocks.findIndex((b:any)=>b.id==='explore');data.blocks.splice(at<0?3:at,0,fresh.blocks.find((b:any)=>b.id==='concepts'))}if(!data.blocks.some((b:any)=>b.id==='land')){const at=data.blocks.findIndex((b:any)=>b.id==='charter');data.blocks.splice(at<0?data.blocks.length:at,0,fresh.blocks.find((b:any)=>b.id==='land'))}if(!data.blocks.find((b:any)=>b.id==='explore')?.resourceItems?.length){const x=data.blocks.find((b:any)=>b.id==='explore');if(x)x.resourceItems=fresh.blocks.find((b:any)=>b.id==='explore').resourceItems}data.teams=(data.teams||[]).map((team:any)=>({...team,charter:{...Object.fromEntries(charterFields.map(([key])=>[key,''])),...(team.charter||{})}}));data.momentTimers=data.momentTimers||{};data.blocks.forEach((b:any)=>{const old=data.momentTimers[b.id],legacy=b.id==='pulse'&&!old?{enabled:data.pulseClockEnabled,remainingSeconds:data.pulseClockSeconds,initialSeconds:data.pulseClockInitialSeconds,running:data.pulseClockRunning,started:data.pulseClockStarted,hasStarted:data.pulseClockHasStarted}:undefined,base=blockSeconds(b),seed=old||legacy||{};data.momentTimers[b.id]={enabled:seed.enabled??b.id==='break',remainingSeconds:seed.remainingSeconds??base,initialSeconds:seed.initialSeconds??base,running:seed.running??false,started:seed.started||0,hasStarted:seed.hasStarted??false}});setState({...fresh,...data});setReady(true)}
  useEffect(()=>{load();const poll=isParticipant?setInterval(()=>load(true),3500):undefined;const clock=setInterval(()=>setNow(Date.now()),1000);return()=>{if(poll)clearInterval(poll);clearInterval(clock)}},[isParticipant,cohort]);
  async function commit(next:State,message="Guardado"){next.executionId=next.executionId||cohort;const r=await fetch(`/api/lab?cohort=${encodeURIComponent(next.executionId)}`,{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify(next)}),data=await r.json().catch(()=>null);if(r.ok){setState({...template(),...(data?.state||next)});setToast(message);return true}setToast(data?.error||"No se pudo guardar");return false;}
  async function adminMutation(operation:string,data:any){const r=await fetch('/api/lab/admin',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({cohort,operation,data})}),result=await r.json().catch(()=>null);if(r.ok&&result?.state){setState({...template(),...result.state});setToast('Base operativa actualizada');return true}setToast(result?.error||'No se pudo actualizar la base operativa.');return false;}
  async function teamAction(action:'join'|'leave',teamId:string,person:any){const r=await fetch('/api/lab',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({cohort,action,teamId,person})}),data=await r.json();if(data.state)setState({...template(),...data.state});setToast(r.ok?(action==='join'?'Equipo actualizado':'Salida del equipo registrada'):(data.error||'No se pudo actualizar el equipo.'));return r.ok}
  function patch(mut:(d:State)=>void,message?:string){const next=structuredClone(state);mut(next);ensureTeamIdentities(next);setState(next);commit(next,message)}
  const sessionNames:any={welcome:'Bienvenida',pulse:'Pulso',instruct:'Instruir',concepts:'Conceptos IA',explore:'Ecosistema IA',prompt:'Aprende a pedir',break:'Break',observe:'Observar',group:'Agrupar',team:'Equipos',land:'Tarjeta reto',share:'Socializar',close:'Cerrar'},blocks=liveBlocks(state).filter((b:any)=>b.id!=='charter').map((b:any)=>({...b,name:sessionNames[b.id]||b.name,...(b.id==='land'?{purpose:'Conviertan su reto en una Tarjeta Reto clara, viable y accionable.',content:'Conversen sobre el problema validado y conéctense con el Asistente del LAB para estructurar la Tarjeta Reto.'}:{})})),activeIndex=Math.max(0,blocks.findIndex((b:any)=>b.id===state.current)),current=blocks[activeIndex]||blocks[0];
  const available=(()=>{const s=state.sessions[0];const [a,b]=s.start.split(":").map(Number),[c,d]=s.end.split(":").map(Number);return Math.max(0,c*60+d-a*60-b)})();
  const remain=clockFor(state,current,now);
  const assigned=blocks.reduce((n:number,b:any)=>n+(Number(b.minutes)||0),0);
  const setMoment=(i:number)=>patch(d=>{const previous=blocks.findIndex((b:any)=>b.id===d.current);if(i>previous)d.completed=[...new Set([...d.completed,...blocks.slice(0,i).map((b:any)=>b.id)])];d.current=blocks[i].id;if(d.current==='team')syncTeams(d)},"Momento actualizado");
  if(!ready)return <main className="loading"><span className="mark">M</span><p>Preparando LAB IA APLICADA</p></main>;
if(isParticipant)return <ParticipantEnhanced state={state} current={current} commit={commit} teamAction={teamAction} pulseClockRemain={clockFor(state,state.blocks.find((b:any)=>b.id==='pulse'),now)} momentClockRemain={remain}/>;
if(present&&current.id==='observe')return <ObservePresentation state={state} current={current} remain={remain} patch={patch} onExit={()=>setPresent(false)} onNext={()=>setMoment(Math.min(blocks.length-1,activeIndex+1))}/>;
if(present&&current.id==='instruct')return <main className="presentation"><button className="presentation-exit" onClick={()=>setPresent(false)}>Salir de presentación</button><div className="present-brand">MENTEVIA HUB <small>LAB IA APLICADA</small></div><InstructGuide state={state} patch={patch} advance={()=>setMoment(Math.min(blocks.length-1,activeIndex+1))}/>{state.momentTimers?.[current.id]?.enabled&&<PresentationClock state={state} block={current} remain={remain} patch={patch}/>}</main>;
if(present&&current.id==='share')return <main className="presentation share-presentation"><button className="presentation-exit" onClick={()=>setPresent(false)}>Salir de presentación</button><div className="present-brand">MENTEVIA HUB <small>LAB IA APLICADA</small></div><SocializarPresentation state={state} remain={remain}/></main>;
  if(present)return <PresentationMode state={state} current={current} blocks={blocks} index={activeIndex} remain={remain} patch={patch} showQR={showQR} setShowQR={setShowQR} onExit={()=>setPresent(false)} onPrev={()=>setMoment(Math.max(0,activeIndex-1))} onNext={()=>setMoment(Math.min(blocks.length-1,activeIndex+1))}/>;
  const nav:[View,any][]=[["home",Home],["configure",Settings2],["live",MonitorUp],["wall",Grid2X2],["teams",Users],["charter",Copy],["data",BarChart3],["solutions",WandSparkles]];
return <main className="app-shell"><aside className={`side ${menuOpen?"":"collapsed"}`}><button className="logo" onClick={()=>setMenuOpen(!menuOpen)}>M</button><div className="nav">{nav.map(([k,I])=><button key={k} title={labels[k]} className={view===k?"selected":""} onClick={()=>setView(k)}><I size={20}/><span>{labels[k]}</span></button>)}</div><div className="side-bottom"><button onClick={()=>setToast("Usa el menú para configurar y facilitar el LAB.")}><CircleHelp size={19}/><span>Ayuda</span></button><small>powered by<br/><b>MenteviaH</b></small></div></aside><section className="workspace"><header className="topbar"><div><button className="mobile-menu" onClick={()=>setMenuOpen(!menuOpen)}><Menu/></button><p className="eyebrow">MENTEVIA HUB</p><p className="descriptor">LAB IA APLICADA</p></div><div className="cohort"><span className={`dot ${statusClass(state.sessions[0].status)}`}/><span>{state.sessions[0].status==="ABIERTA"?"Sesión abierta":"Cohorte piloto"}</span><button className="icon-button" onClick={()=>setShowQR(true)}><QrCode size={19}/></button></div></header>{view==="home"&&<HomeView state={state} setView={setView} setShowQR={setShowQR} patch={patch}/>} {view==="configure"&&<><Configure state={state} patch={patch} available={available} assigned={assigned}/><PulseConfigurator state={state} patch={patch}/><ResourceManager state={state} patch={patch}/></>} {view==="live"&&<Live state={state} current={current} blocks={blocks} activeIndex={activeIndex} remain={remain} patch={patch} setMoment={setMoment} setPresent={setPresent} setShowQR={setShowQR}/>} {view==="wall"&&<Wall state={state} patch={patch} setView={setView}/>} {view==="teams"&&<Teams state={state} patch={patch} setView={setView}/>} {view==="charter"&&<Charter state={state} patch={patch}/>} {view==="data"&&<LabData state={state}/>} {view==="solutions"&&<Solutions state={state} patch={patch}/>}</section>{showQR&&<QRModal state={state} onClose={()=>setShowQR(false)}/>} {toast&&<button className="toast" onClick={()=>setToast("")}>{toast}<X size={15}/></button>}</main>;
}

function HomeView({state,setView,setShowQR,patch}:any){return <div className="home-view"><section className="hero"><div className="hero-copy"><p className="eyebrow violet">EXPERIENCIA ACTIVA</p><h1>Inteligencia<br/>Artificial <em>aplicada a</em><br/>{state.sector}</h1><p className="subtle">{state.organization}</p><div className="hero-actions"><button className="primary" onClick={()=>{patch((d:any)=>d.sessions[0].status="ABIERTA","Sesión 1 abierta");setView("live")}}><Play size={17} fill="currentColor"/>Entrar a sesión activa</button><button className="secondary" onClick={()=>setShowQR(true)}><QrCode size={18}/>Mostrar QR</button></div></div><div className="aurora"><div className="orb a"/><div className="orb b"/><div className="glass-card"><span>01</span><p>IDENTIFICAR<br/>+ EXPLORAR</p></div></div></section><section className="sessions">{state.sessions.map((s:any,i:number)=><button key={i} className={`session-card ${i===0?"active":""}`} onClick={()=>i===0&&setView("live")}><span className="number">0{i+1}</span><span><b>{s.name}</b><small className={statusClass(s.status)}>{s.status}</small></span>{i>0&&<span className="lock">⌑</span>}</button>)}</section><section className="facts"><span><Clock3/>{state.totalHours} horas</span><span><Users/>{state.estimated} participantes estimados</span><span><BarChart3/>Motor configurable</span></section></div>}

function Configure({state,patch,available,assigned}:any){const auto=()=>patch((d:any)=>{const bs=liveBlocks(d),open=bs.filter((b:any)=>b.id!=="break"),n=Math.max(0,available-20);open.forEach((b:any)=>b.minutes=Math.floor(n/open.length));open[open.length-1].minutes+=n-open.reduce((x:number,b:any)=>x+b.minutes,0);d.blocks.find((b:any)=>b.id==="break").minutes=20},"Tiempos propuestos para el piloto");return <div className="page configure"><div className="page-heading"><div><p className="eyebrow violet">CONFIGURACIÓN DE COHORTE</p><h2>El motor y el contexto</h2><p>Metodología base separada del vestido sectorial.</p></div><button className="secondary" onClick={auto}><RotateCcw size={16}/>Distribuir automáticamente</button></div><section className="config-grid"><div className="panel"><h3>Cohorte / ejecución</h3><div className="form-grid">{[["executionId","Código de ejecución"],["name","Nombre de experiencia"],["sector","Área / sector"],["organization","Organización"],["program","Programa / laboratorio"],["institutionalContact","Contacto institucional"],["price","Precio"],["modality","Modalidad"],["location","Ubicación o enlace"],["estimated","Participantes estimados"],["teamMin","Mínimo por equipo"],["teamMax","Máximo por equipo"]].map(([k,l])=><label key={k}>{l}<input value={state[k]??""} onChange={e=>patch((d:any)=>d[k]=["estimated","teamMin","teamMax"].includes(k)?Number(e.target.value):e.target.value,"Configuración guardada")}/></label>)}</div><label className="wide">Vestido sectorial<input value={state.sectorContext} onChange={e=>patch((d:any)=>d.sectorContext=e.target.value,"Contexto actualizado")}/></label><label className="wide help-toggle">NECESITO AYUDA <input type="checkbox" checked={state.helpEnabled??true} onChange={e=>patch((d:any)=>d.helpEnabled=e.target.checked,"Ayuda actualizada")}/></label></div><div className="panel time-panel"><h3>Planificador dinámico · Sesión 1</h3><div className="time-stats"><div><small>Tiempo disponible</small><b>{available} min</b></div><div><small>Tiempo asignado</small><b>{assigned} min</b></div><div className={assigned>available?"over":""}><small>{assigned>available?"Excedido":"Pendiente"}</small><b>{Math.abs(available-assigned)} min</b></div></div><p className="helper">Los tiempos son ajustes de piloto: el Documento Maestro no fija un minuto a minuto universal.</p></div><div className="panel database-access"><small>BASE DE DATOS DEL LAB</small><a className="secondary link" href={state.labDatabaseUrl} target="_blank" rel="noreferrer"><ExternalLink size={16}/>Abrir Google Sheet ↗</a></div></section><section className="panel session-editor"><h3>Sesiones de la ejecución</h3>{state.sessions.map((s:any,i:number)=><div className="session-row" key={i}><span className="index">0{i+1}</span><input value={s.name} onChange={e=>patch((d:any)=>d.sessions[i].name=e.target.value,"Sesión actualizada")}/><input type="date" value={s.date} onChange={e=>patch((d:any)=>d.sessions[i].date=e.target.value,"Fecha actualizada")}/><input type="time" value={s.start} onChange={e=>patch((d:any)=>d.sessions[i].start=e.target.value,"Horario actualizado")}/><input type="time" value={s.end} onChange={e=>patch((d:any)=>d.sessions[i].end=e.target.value,"Horario actualizado")}/><select value={s.status} onChange={e=>patch((d:any)=>d.sessions[i].status=e.target.value,"Estado actualizado")}>{["BORRADOR","BLOQUEADA","ABIERTA","FINALIZADA"].map(x=><option key={x}>{x}</option>)}</select></div>)}</section><section className="panel library"><div className="library-title"><div><h3>Biblioteca de bloques · Sesión 1</h3><p>Orden recomendado; puedes activar, mostrar y ajustar tiempos.</p></div><span className="badge">{liveBlocks(state).length} activos</span></div>{state.blocks.map((b:any,i:number)=><div className={`block-row ${!b.active?"inactive":""}`} key={b.id}><div className="drag">⠿</div><div className="block-main"><b>{b.name}</b><small>{b.phase} · {b.type}</small></div><label className="switch"><input type="checkbox" checked={b.active} onChange={e=>patch((d:any)=>d.blocks.find((x:any)=>x.id===b.id).active=e.target.checked,"Bloque actualizado")}/><span/></label><button className="eye" onClick={()=>patch((d:any)=>d.blocks.find((x:any)=>x.id===b.id).visible=!b.visible,"Visibilidad actualizada")}>{b.visible?<Eye size={17}/>:<EyeOff size={17}/>}</button><input className="minute" type="number" min="0" value={b.minutes} onChange={e=>patch((d:any)=>d.blocks.find((x:any)=>x.id===b.id).minutes=Number(e.target.value),"Tiempo actualizado")}/><small>min</small><div className="reorder"><button disabled={i===0} onClick={()=>patch((d:any)=>{[d.blocks[i-1],d.blocks[i]]=[d.blocks[i],d.blocks[i-1]]},"Orden actualizado")}>↑</button><button disabled={i===state.blocks.length-1} onClick={()=>patch((d:any)=>{[d.blocks[i+1],d.blocks[i]]=[d.blocks[i],d.blocks[i+1]]},"Orden actualizado")}>↓</button></div></div>)}</section></div>}

function PulseConfigurator({state,patch}:any){const qs=state.pulseConfig||pulseDefaults;return <section className="page pulse-config"><div className="page-heading"><div><p className="eyebrow violet">CONFIGURADOR · PULSO INICIAL</p><h2>Diagnóstico de entrada</h2><p>Las preguntas activas determinan el Live y el dashboard de esta ejecución.</p></div></div><section className="panel"><h3>Preguntas configuradas</h3>{qs.map((q:any,i:number)=><div className="pulse-config-row" key={q.id}><span>{i+1}</span><div><b>{q.title}</b><small>{q.kind==='multi'?'Selección múltiple':q.kind==='scale'?'Escala 1–5':'Respuesta única'}</small></div><label className="switch"><input type="checkbox" checked={q.active} onChange={e=>patch((d:any)=>d.pulseConfig.find((x:any)=>x.id===q.id).active=e.target.checked,"Pregunta de Pulso actualizada")}/><span/></label><button disabled={i===0} onClick={()=>patch((d:any)=>{[d.pulseConfig[i-1],d.pulseConfig[i]]=[d.pulseConfig[i],d.pulseConfig[i-1]]},"Orden de Pulso actualizado")}>↑</button><button disabled={i===qs.length-1} onClick={()=>patch((d:any)=>{[d.pulseConfig[i+1],d.pulseConfig[i]]=[d.pulseConfig[i],d.pulseConfig[i+1]]},"Orden de Pulso actualizado")}>↓</button></div>)}</section></section>}
function ResourceManager({state,patch}:any){
  const [blockId,setBlockId]=useState(state.blocks[0]?.id||""),[draft,setDraft]=useState<any>({name:"",description:"",type:"GOOGLE_SLIDES",url:"",viewMode:"EMBEBIDO",participantVisible:false,facilitatorVisible:true,generateQR:true,active:true}),[qr,setQr]=useState("");
  const block=state.blocks.find((b:any)=>b.id===blockId)||state.blocks[0],ctaBlock=block?.id==='charter'?(state.blocks.find((b:any)=>b.id==='land')||block):block,items=block?.resourceItems||[],canConfigureCta=['prompt','land','charter'].includes(block?.id);
  const update=(id:string,mut:(r:any)=>void,msg="Recurso actualizado")=>patch((d:any)=>mut(d.blocks.find((b:any)=>b.id===blockId).resourceItems.find((r:any)=>r.id===id)),msg);
  const add=()=>{if(!draft.name.trim()||!draft.url.trim())return;patch((d:any)=>{const b=d.blocks.find((x:any)=>x.id===blockId);b.resourceItems=b.resourceItems||[];b.resourceItems.push({...draft,id:crypto.randomUUID(),order:b.resourceItems.length})},"Recurso guardado");setDraft({...draft,name:"",description:"",url:""})};
  const changeCta=(key:string,value:any)=>patch((d:any)=>{const b=d.blocks.find((x:any)=>x.id===ctaBlock?.id);b.cta={...(b.cta||{}),[key]:value}},"CTA actualizado");
return <section className="resource-admin"><div className="page resource-page"><div className="page-heading"><div><p className="eyebrow violet">RECURSOS EXTERNOS</p><h2>Contenido académico por bloque</h2><p>Slides, experiencias web y copilotos se administran por URL; el motor LAB conserva metodología y datos.</p></div></div><div className="resource-layout"><section className="panel"><h3>Bloque metodológico</h3><select value={blockId} onChange={e=>setBlockId(e.target.value)}>{state.blocks.map((b:any)=><option value={b.id} key={b.id}>{b.name}</option>)}</select>{canConfigureCta&&<section className="cta-config"><h3 className="resource-section-title">CTA de {ctaBlock?.name}</h3><label>Texto del botón<input value={ctaBlock?.cta?.text||ctaDefaults[ctaBlock?.id]?.text||''} onChange={e=>changeCta('text',e.target.value)}/></label><label>URL / hipervínculo<input type="url" placeholder="https://chatgpt.com/g/..." value={ctaBlock?.cta?.url||''} onChange={e=>changeCta('url',e.target.value)}/></label><label className="switch">Activo<input type="checkbox" checked={ctaBlock?.cta?.active??true} onChange={e=>changeCta('active',e.target.checked)}/><span/></label></section>}<h3 className="resource-section-title">Recursos de {block?.name}</h3>{items.length===0?<p className="empty">Este bloque todavía no tiene recursos externos.</p>:items.sort((a:any,b:any)=>a.order-b.order).map((r:any,i:number)=><article className={`resource-row ${!r.active?"inactive":""}`} key={r.id}><div><b>{r.name}</b><small>{r.type} · {r.viewMode}</small><p>{r.url}</p></div><div className="resource-actions"><button onClick={()=>update(r.id,(x:any)=>x.active=!x.active,x=>x.active?"Recurso activado":"Recurso desactivado")}><Eye size={16}/></button><button onClick={()=>setQr(r.url)} disabled={!r.generateQR}><QrCode size={16}/></button><button onClick={()=>patch((d:any)=>{const list=d.blocks.find((b:any)=>b.id===blockId).resourceItems;list.splice(i,1);list.forEach((x:any,j:number)=>x.order=j)},"Recurso eliminado")}>×</button></div></article>)}</section><section className="panel resource-form"><h3>Agregar recurso</h3><label>Nombre<input value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/></label><label>Descripción breve<input value={draft.description} onChange={e=>setDraft({...draft,description:e.target.value})}/></label><div className="form-grid"><label>Tipo<select value={draft.type} onChange={e=>setDraft({...draft,type:e.target.value})}>{["GOOGLE_SLIDES","HTML_WEB","GPT_CHATGPT","VIDEO","DOCUMENTO","ENLACE","RECURSO_INTERNO_LAB"].map(x=><option key={x}>{x}</option>)}</select></label><label>Visualización<select value={draft.viewMode} onChange={e=>setDraft({...draft,viewMode:e.target.value})}>{["EMBEBIDO","PANTALLA_COMPLETA","NUEVA_PESTAÑA"].map(x=><option key={x}>{x}</option>)}</select></label></div><label>URL<input type="url" placeholder="https://…" value={draft.url} onChange={e=>setDraft({...draft,url:e.target.value})}/></label><div className="resource-checks"><label><input type="checkbox" checked={draft.participantVisible} onChange={e=>setDraft({...draft,participantVisible:e.target.checked})}/>Mostrar a participantes</label><label><input type="checkbox" checked={draft.facilitatorVisible} onChange={e=>setDraft({...draft,facilitatorVisible:e.target.checked})}/>Mostrar a facilitador</label><label><input type="checkbox" checked={draft.generateQR} onChange={e=>setDraft({...draft,generateQR:e.target.checked})}/>Generar QR</label><label><input type="checkbox" checked={draft.active} onChange={e=>setDraft({...draft,active:e.target.checked})}/>Activo</label></div><button className="primary" onClick={add}><Plus size={17}/>Guardar recurso</button></section></div></div>{qr&&<QRModal state={state} target={qr} title="RECURSO DEL BLOQUE" onClose={()=>setQr("")}/>}</section>
}

function ResourceViewer({resource,compact=false}:any){if(!resource)return null;if(resource.type==="GPT_CHATGPT"||resource.viewMode==="NUEVA_PESTAÑA")return <div className="resource-viewer fallback"><p className="eyebrow violet">{resource.type}</p><h3>{resource.name}</h3>{resource.description&&<p>{resource.description}</p>}<a className="primary link" href={resource.url} target="_blank"><ExternalLink size={16}/>{resource.type==="GPT_CHATGPT"?"Abrir Copiloto LAB":"Abrir recurso"}</a></div>;return <div className={`resource-viewer ${compact?"compact":""}`}><div className="resource-viewer-head"><span>{resource.type.replace("_"," ")}</span><a href={resource.url} target="_blank">Abrir original <ExternalLink size={14}/></a></div><iframe src={resource.url} title={resource.name} allow="fullscreen"/><div className="resource-fallback"><p>Si el sitio no permite mostrarse dentro de LAB:</p><a className="secondary" href={resource.url} target="_blank">Abrir experiencia <ExternalLink size={15}/></a></div></div>}

function FacilitatorClock({state,block,remain,patch}:any){const enabled=!!state.momentTimers?.[block?.id]?.enabled,show=()=>patch((d:any)=>{const base=blockSeconds(block);d.momentTimers=d.momentTimers||{};d.momentTimers[block.id]=d.momentTimers[block.id]||{enabled:false,remainingSeconds:base,initialSeconds:base,running:false,started:0,hasStarted:false};d.momentTimers[block.id].enabled=true},'Reloj mostrado');return enabled?<ShareClock state={state} patch={patch} remain={remain} block={block}/>:<button className="ficha-clock-toggle canonical-clock-trigger" onClick={show}>◷ Mostrar reloj &gt;</button>}

const challengeExample={radar:'OPERACIÓN',title:'Evaluación de hojas de vida',context:'Evaluar 80 hojas de vida según los criterios definidos para una convocatoria.',friction:'Revisar manualmente mucha información en documentos con formatos diferentes.',problem:'Toma demasiado tiempo y dificulta comparar candidatos de manera consistente.'};
function ChallengeCard({data,preview=false}:any){const value=(key:string,placeholder:string)=>data?.[key]||placeholder;return <article className={`challenge-card ${preview?'preview':''}`}><small>RETO{data?.radar?` · ${data.radar}`:''}</small><h3>{value('title','Nombre del reto')}</h3><span className="challenge-line"/><div><b>QUÉ NECESITO HACER</b><p>{value('context','Describe la tarea concreta que realizas.')}</p></div><div><b>QUÉ LO HACE DIFÍCIL</b><p>{value('friction','¿Qué te quita tiempo, genera errores o complica esta tarea?')}</p></div><div><b>IMPACTO</b><p>{value('problem','¿Qué pasa como consecuencia de esa dificultad?')}</p></div><footer>○ Oportunidad</footer></article>}
function ChallengeFields({data,setData}:any){const fields=[['title','Nombre del reto','Una forma breve de identificarlo.','Ej. Evaluación de hojas de vida'],['context','¿Qué necesito hacer?','Describe la tarea concreta que realizas.','Ej. Evaluar 80 hojas de vida según los criterios definidos para una convocatoria.'],['friction','¿Qué lo hace difícil?','¿Qué te quita tiempo, genera errores o complica esta tarea?','Ej. Revisar manualmente mucha información en documentos con formatos diferentes.'],['problem','¿Qué impacto tiene?','¿Qué pasa como consecuencia de esa dificultad?','Ej. Toma demasiado tiempo y dificulta comparar candidatos de manera consistente.']];return <div className="challenge-fields">{fields.map(([key,label,help,placeholder])=><label key={key}><b>{label}</b><small>{help}</small>{key==='title'?<input value={data[key]||''} placeholder={placeholder} onChange={e=>setData({...data,[key]:e.target.value})}/>:<textarea value={data[key]||''} placeholder={placeholder} onChange={e=>setData({...data,[key]:e.target.value})}/>}</label>)}</div>}
function ReframeGuide(){const fields=[['Nombre del reto','Una forma breve de identificarlo.'],['¿Qué necesito hacer?','Describe la tarea concreta que realizas.'],['¿Qué lo hace difícil?','¿Qué te quita tiempo, genera errores o complica esta tarea?'],['¿Qué impacto tiene?','¿Qué pasa como consecuencia de esa dificultad?']];return <div className="reframe-guide"><section><b>Estructura de la tarjeta de reto</b>{fields.map(([title,copy])=><div key={title}><strong>{title}</strong><small>{copy}</small></div>)}</section><section><b>Ejemplo de tarjeta de reto</b><ChallengeCard data={challengeExample}/></section></div>}
function ChallengeWall({state,audience='facilitator',onEdit,onDelete}:any){const [filter,setFilter]=useState('Todos'),categories=Array.from(new Set(state.opportunities.map((o:any)=>o.radar).filter(Boolean))),items=filter==='Todos'?state.opportunities:state.opportunities.filter((o:any)=>o.radar===filter);return <section className="challenge-wall"><div className="challenge-wall-heading"><div><h3>Retos del grupo.</h3><p>{audience==='participant'?'Explora los retos que han compartido tus compañeros en tiempo real.':'Visualiza en tiempo real los aportes de los participantes.'}</p></div>{audience==='facilitator'&&<b>{state.opportunities.length} aportes</b>}</div>{(categories.length>0||state.opportunities.length>0)&&<div className="challenge-filters"><button className={filter==='Todos'?'active':''} onClick={()=>setFilter('Todos')}>Todos {state.opportunities.length}</button>{categories.map((c:any)=><button key={c} className={filter===c?'active':''} onClick={()=>setFilter(c)}>{c} {state.opportunities.filter((o:any)=>o.radar===c).length}</button>)}</div>}<div className="challenge-wall-grid">{items.length?items.map((o:any)=><div key={o.id}><ChallengeCard data={o}/>{onEdit&&<div className="admin-actions challenge-admin-actions"><button className="secondary data-action" onClick={()=>onEdit(o)}>Editar</button><button className="secondary data-action danger" onClick={()=>onDelete(o)}>Eliminar</button></div>}</div>):<p className="empty">Aún no hay retos registrados.</p>}</div></section>}
function AdminChallengeWall({state,onAdmin}:any){
  const [editing,setEditing]=useState<any>(null),[notice,setNotice]=useState('');
  const admin=onAdmin||((operation:string,data:any)=>runOperationalAdmin(state,operation,data));
  const session_id=state.executionId||'piloto-gestion-humana';
  const persistChallenge=async(record:any)=>admin('admin_upsert',{entity:'challenge',record:{session_id:record.session_id||session_id,challenge_id:record.challenge_id,title:record.title||'',context:record.context||'',friction:record.friction||'',impact:record.impact||'',status:record.status||'registered'}});
  const create=()=>{setNotice('');setEditing({session_id,challenge_id:crypto.randomUUID(),title:'',context:'',friction:'',impact:'',status:'registered'});};
  const edit=(item:any)=>setEditing({session_id:item.sheetSessionId||session_id,challenge_id:item.id,title:item.title,context:item.context,friction:item.friction,impact:item.problem,status:item.status||'registered'});
  const save=async(draft:any)=>{try{setNotice('');await persistChallenge(draft);setEditing(null)}catch(error:any){setNotice(error?.message||'No fue posible guardar el reto.')}};
  const remove=async(item:any)=>{if(!window.confirm('¿Eliminar este reto? Si pertenece a un clúster o equipo, primero deberás resolver esas asociaciones. Esta acción no se puede deshacer.'))return;try{setNotice('');await admin('admin_delete',{entity:'challenge',id:item.id,session_id:item.sheetSessionId||session_id});}catch(error:any){setNotice(error?.message||'No fue posible eliminar el reto.')}};
  return <><div className="challenge-admin-toolbar"><button className="primary" onClick={create}><Plus size={16}/>Crear reto</button></div><ChallengeWall state={state} onEdit={edit} onDelete={remove}/>{editing&&<AdminEditor kind="challenge" record={editing} state={state} onCancel={()=>setEditing(null)} onSave={save}/>} {notice&&<p className="admin-error" role="alert">{notice}</p>}</>}

function ParticipantClusterWall({state}:any){const unassigned=state.opportunities.filter((o:any)=>!state.clusters.some((c:any)=>c.opportunityIds.includes(o.id)));return <div className="participant-cluster-wall"><p className="eyebrow violet">AGRUPAR · MURO EN VIVO</p><h3>Retos y clústers del grupo</h3><p className="hint">Propuesta automática generada con IA. Requiere validación humana.</p>{unassigned.length>0&&<section><h4>Sin agrupar · {unassigned.length}</h4><div className="challenge-wall-grid">{unassigned.map((o:any)=><ChallengeCard key={o.id} data={o}/>)}</div></section>}<div className="participant-cluster-grid">{state.clusters.map((c:any)=>{const items=state.opportunities.filter((o:any)=>c.opportunityIds.includes(o.id));return <article className={`participant-cluster ${c.status==='VALIDADO'?'validated':''}`} key={c.id}><header><b>{c.name}</b><span>{c.status==='VALIDADO'?'✓ Clúster validado':'En revisión'}</span></header><small>{items.length} retos</small><div><strong>POV · Propuesta IA</strong><p>{c.pov||'Por validar con el grupo.'}</p></div><div><strong>Pregunta reto · Propuesta IA</strong><p>{c.hmw||'Por formular con el grupo.'}</p></div><div className="challenge-wall-grid">{items.map((o:any)=><ChallengeCard key={o.id} data={o}/>)}</div></article>})}</div></div>}
function RegisterGuide({state}:any){return <div className="register-guide"><section><b>Ejemplo de tarjeta de reto</b><ChallengeCard data={challengeExample}/></section><ChallengeWall state={state}/></div>}
function ObserveContent({item,state,audience='facilitator'}:any){const grid:any={display:'grid',gridTemplateColumns:'repeat(2,minmax(0,1fr))',gap:10,margin:'25px 0'};return <>{item.items&&<div style={grid}>{item.items.map((x:string)=><span key={x} style={{padding:13,border:'1px solid #e9e5f1',borderRadius:10,background:'#fff'}}>✓ {x}</span>)}</div>}{item.id==='reframe'?<ReframeGuide/>:item.id==='register'?<RegisterGuide state={state}/>:item.note&&<div style={{padding:16,borderRadius:12,background:'#f4efff',color:'#4c2aa7',margin:'24px 0'}}>{item.note}</div>}</>}
function ObserveGuide({state,patch,onWall,onNext}:any){const steps=state.observeConfig||observeDefaults,step=Math.max(0,Math.min(steps.length-1,state.observeStep||0)),item=steps[step],register=item.id==='register',go=(n:number)=>patch((d:any)=>d.observeStep=Math.max(0,Math.min((d.observeConfig||observeDefaults).length-1,n)),'Subsección de Observar actualizada'),track:any={display:'flex',gap:10,overflowX:'auto',paddingBottom:20,marginBottom:18},tab=(i:number):any=>({border:'1px solid #e9e5f1',background:i===step?'#f0e9ff':'#fff',color:'#21154f',borderRadius:10,padding:'8px 11px',display:'inline-flex',alignItems:'center',gap:7,whiteSpace:'nowrap',fontWeight:i===step?'bold':'normal'}),nav:any={display:'flex',justifyContent:'space-between',marginTop:28};return <section className="observe-guide"><div style={track}>{steps.map((s:any,i:number)=><button key={s.id} style={tab(i)} onClick={()=>go(i)}><span style={{width:25,height:25,borderRadius:'50%',display:'grid',placeItems:'center',background:i===step?'#7441ef':'#f5f1ff',color:i===step?'#fff':'#6338e7'}}>{i+1}</span>{s.name}</button>)}</div><p className="eyebrow violet">MOMENTO 8 · OBSERVAR · {String(step+1).padStart(2,'0')} · {item.name.toUpperCase()}</p><h1>{item.title}</h1><div className="rule"/><p className="consigna">{item.content}</p><ObserveContent item={item} state={state}/>{register&&<button className="secondary" style={{marginTop:16}} onClick={onWall}>Ir al Muro de retos →</button>}<div style={nav}><button className="secondary" disabled={step===0} onClick={()=>go(step-1)}>← Anterior</button><button className="primary" onClick={()=>register?onNext?.():go(step+1)}>Siguiente →</button></div></section>}
function ObservePresentation({state,current,remain,patch,onExit,onNext}:any){const [wallOpen,setWallOpen]=useState(false),steps=state.observeConfig||observeDefaults,step=Math.max(0,Math.min(steps.length-1,state.observeStep||0)),item=steps[step],register=item.id==='register',go=(n:number)=>patch((d:any)=>d.observeStep=Math.max(0,Math.min((d.observeConfig||observeDefaults).length-1,n)),'Subsección de Observar actualizada'),enabled=!!state.momentTimers?.[current.id]?.enabled,header=<header style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:24,padding:'26px 7vw 0'}}><div className="present-brand" style={{position:'static'}}>MENTEVIA HUB · LAB IA APLICADA<small>{state.program||state.name}<br/>{state.organization}</small></div><div style={{display:'grid',justifyItems:'end',gap:12}}><button className="presentation-exit" style={{position:'static'}} onClick={onExit}>Salir de presentación</button><small className="eyebrow">SESIÓN 01 · 08/14</small></div></header>;if(wallOpen)return <main className="presentation">{header}<article style={{marginTop:38}}><p className="eyebrow violet">MOMENTO 08 · OBSERVAR · MURO DE RETOS</p><h1>Retos del grupo</h1><p className="present-content">Aportes recibidos en tiempo real durante la actividad.</p><ChallengeWall state={state}/><div className="present-bottom"><button className="secondary" onClick={()=>setWallOpen(false)}>← Volver a Registra tu reto</button></div></article></main>;return <main className="presentation">{header}<article style={{marginTop:38}}><p className="eyebrow violet">MOMENTO 08 · OBSERVAR · {String(step+1).padStart(2,'0')} · {item.name.toUpperCase()}</p><div style={{display:'flex',gap:9,overflowX:'auto',padding:'8px 0 22px'}}>{steps.map((s:any,i:number)=><button key={s.id} onClick={()=>go(i)} style={{border:'1px solid #e9e5f1',background:i===step?'#f0e9ff':'#fff',color:'#21154f',borderRadius:10,padding:'8px 11px',whiteSpace:'nowrap',fontWeight:i===step?'bold':'normal'}}>{String(i+1).padStart(2,'0')} {s.name}</button>)}</div><h1>{item.title}</h1><span className="present-line"/><h2>{item.content}</h2><ObserveContent item={item} state={state}/>{register&&<button className="secondary" style={{marginTop:16}} onClick={()=>setWallOpen(true)}>Ir al Muro de retos →</button>}<div className="present-bottom"><button onClick={()=>go(step-1)} disabled={step===0}>← Anterior</button>{enabled&&<PresentationClock state={state} block={current} remain={remain} patch={patch}/>} <button className="primary" onClick={()=>register?onNext?.():go(step+1)}>Siguiente →</button></div></article></main>}

function Live({state,current,blocks,activeIndex,remain,patch,setMoment,setPresent,setShowQR}:any){
  const resource=(current?.resourceItems||[]).filter((r:any)=>r.active&&r.facilitatorVisible)[0];
  const [wallOpen,setWallOpen]=useState(false),[dragged,setDragged]=useState<string|null>(null);
  const reorder=(from:string,to:string)=>patch((d:any)=>{const a=d.blocks.findIndex((x:any)=>x.id===from),b=d.blocks.findIndex((x:any)=>x.id===to);if(a<0||b<0||a===b)return;const [item]=d.blocks.splice(a,1);d.blocks.splice(b,0,item)},'Orden de momentos actualizado');
  if(current?.id==='group'&&wallOpen)return <div className="page live"><button className="secondary" onClick={()=>setWallOpen(false)}>← Volver a Agrupar</button><Wall state={state} patch={patch} setView={()=>{}}/></div>;
  if(current?.id==='observe'&&wallOpen)return <div className="page live"><button className="secondary" onClick={()=>setWallOpen(false)}>← Volver a Registra tu reto</button><div className="page-heading"><div><p className="eyebrow violet">OBSERVAR · MURO DE RETOS</p><h2>Muro de retos</h2><p>Administra los aportes recuperados desde la base operativa.</p></div></div><AdminChallengeWall state={state}/></div>;
  const advance=(offset:number)=>setMoment(Math.max(0,Math.min(blocks.length-1,activeIndex+offset)));
  let activity:any;
  if(current?.id==='pulse')activity=<PulseFacilitator state={state} current={current} remain={remain} patch={patch} setPresent={setPresent}/>;
  else if(current?.id==='prompt')activity=<div className="live-grid"><PromptGuide state={state} patch={patch} advance={()=>advance(1)}/><FacilitatorClock state={state} block={current} remain={remain} patch={patch} className="facilitator"/></div>;
  else if(current?.id==='instruct')activity=<div className="live-grid"><InstructGuide state={state} patch={patch} advance={()=>advance(1)}/><FacilitatorClock state={state} block={current} remain={remain} patch={patch} className="facilitator"/></div>;
  else if(current?.id==='team')activity=<div className="live-grid"><TeamFacilitator state={state} patch={patch}/><FacilitatorClock state={state} block={current} remain={remain} patch={patch}/></div>;
  else if(current?.id==='land')activity=<div className="live-grid"><RetoGuide state={state} patch={patch} facilitator advance={()=>advance(1)}/><FacilitatorClock state={state} block={current} remain={remain} patch={patch}/></div>;
  else if(current?.id==='share')activity=<ShareGuide state={state} patch={patch} advance={advance} remain={remain}/>;
  else activity=<section className="live-grid"><article className="moment-card">{current?.id==='observe'?<ObserveGuide state={state} patch={patch} onWall={()=>setWallOpen(true)}/>:<><p className="eyebrow violet">MOMENTO {activeIndex+1} · {current?.phase}</p><h1>{current?.name}</h1><div className="rule"/><p className="consigna">{current?.content}</p><div className="moment-method"><b>METODOLOGÍA</b><p>{current?.methodology}</p></div>{current?.id==='group'&&<button className="secondary" onClick={()=>setWallOpen(true)}>← Ver Muro de retos</button>}{resource&&<ResourceViewer resource={resource} compact/>}</>}</article><FacilitatorClock state={state} block={current} remain={remain} patch={patch} className="facilitator"/></section>;
  return <div className="page live"><div className="live-top"><div><p className="eyebrow">MENTEVIA HUB · LAB IA APLICADA</p><p className="execution-context">{state.program||state.name} · {state.organization} · {state.sessions[0].date}</p><p className="eyebrow violet">SESIÓN 01 · {state.sessions[0].status}</p><h2>Identificar <em>+ explorar</em></h2></div><div className="live-actions"><button className="secondary" onClick={()=>setShowQR(true)}><QrCode size={17}/>QR de acceso</button><button className="primary" onClick={()=>setPresent(true)}><Presentation size={17}/>Modo presentación</button></div></div><div className="moment-track">{blocks.map((b:any,i:number)=><button draggable key={b.id} className={`${i===activeIndex?'now':state.completed.includes(b.id)?'done':''} ${dragged===b.id?'dragging':''}`} onDragStart={()=>setDragged(b.id)} onDragOver={e=>e.preventDefault()} onDrop={()=>{if(dragged)reorder(dragged,b.id);setDragged(null)}} onDragEnd={()=>setDragged(null)} onClick={()=>setMoment(i)}><span>{i+1}</span><small>{b.name}</small></button>)}</div>{activity}<section className="facilitator-status"><div><small>Participantes conectados</small><b>{state.participants.length}</b></div><div><small>Pulsos recibidos</small><b>{state.participants.filter((p:any)=>p.pulseResponses).length}</b></div><div><small>Retos recibidos</small><b>{state.opportunities.length}</b></div><div><small>Clusters</small><b>{state.clusters.length}</b></div><div><small>Equipos</small><b>{state.teams.length}</b></div><div><small>Solicitudes de ayuda</small><b>{state.help.length}</b></div></section></div>}

function PulseResultCard({q,people,expanded=false}:any){const count=(o:string)=>people.filter((p:any)=>(Array.isArray(p.pulseResponses[q.id])?p.pulseResponses[q.id]:[p.pulseResponses[q.id]]).includes(o)).length,percent=(o:string)=>people.length?Math.round(count(o)/people.length*100):0,sort=q.id==='tasks',options=sort?[...q.options].sort((a:string,b:string)=>count(b)-count(a)):q.options,top=options.reduce((best:string,o:string)=>count(o)>count(best)?o:best,q.options[0]),ties=people.length?q.options.filter((o:string)=>count(o)===count(top)):[],avg=q.id==='confidence'&&people.length?people.reduce((n:number,p:any)=>n+Number(p.pulseResponses[q.id]||0),0)/people.length:0,label=avg>=4.5?'Muy seguro/a':avg>=3.5?'Seguro/a':avg>=2.5?'Seguridad intermedia':avg>=1.5?'Con poca seguridad':'Inseguro/a',title=q.id==='frequency'?'FRECUENCIA DE USO':q.id==='autonomy'?'NIVEL DE AUTONOMÍA CON IA':q.id==='tasks'?'PRINCIPALES USOS DE IA':'SEGURIDAD PERCIBIDA',number=q.id==='frequency'?'1':q.id==='autonomy'?'2':q.id==='tasks'?'3':'4';const Bars=()=> <div className="dash-bars">{options.map((o:string)=><div key={o}><span>{o}</span><i style={{width:percent(o)+"%"}}/><b>{percent(o)}% · {count(o)}</b></div>)}</div>;return <section className={'dash-card '+q.id+(expanded?' expanded-result':'')}><span className="card-index">{number}</span><small>{title}</small><p className="dash-question">{q.title}</p>{q.id==='confidence'?<div className="security-layout"><div className="security-average"><span>PROMEDIO DEL GRUPO</span><strong>{avg.toFixed(1)} / 5</strong><b>{label}</b><small>1 = Inseguro/a<br/>5 = Muy seguro/a</small></div><div className="security-columns">{q.options.map((o:string)=><div key={o}><b>{percent(o)}%</b><i style={{height:Math.max(6,percent(o))+"%"}}/><span>{o}</span></div>)}</div></div>:<><div className="dash-highlight"><strong>{people.length?percent(top):0}%</strong><b>{!people.length?'Sin respuestas todavía':q.id==='tasks'&&ties.length>1?<><span>Usos más frecuentes</span>{ties.map((x:string)=><em key={x}>{x}</em>)}</>:top}</b></div><Bars/>{q.id==='tasks'&&<p className="multi-note">Selección múltiple: los porcentajes no necesariamente suman 100%.</p>}</>}</section>}

function PulseDashboard({state,qs,people,final=false}:any){return <><header className="pulse-dashboard-heading"><div><p className="eyebrow violet">PULSO INICIAL · {final?'PULSO FINALIZADO':'RESULTADOS EN VIVO'}</p><h1>Así llega este grupo</h1><p>Una primera mirada para diseñar la experiencia de hoy.</p></div></header><div className="dashboard-kpis"><div><small>PARTICIPANTES CONECTADOS</small><b>{state.participants.length}</b></div><div><small>RESPUESTAS RECIBIDAS</small><b>{people.length}</b></div><div><small>% PARTICIPACIÓN</small><b>{state.participants.length?Math.round(people.length/state.participants.length*100):0}%</b></div></div><div className="pulse-dashboard-grid">{qs.map((q:any)=><PulseResultCard key={q.id} q={q} people={people}/>)}</div></>}

function PulseQuestionSummary({q,people}:any){return <PulseQuestionLive q={q} people={people}/>}

function PulseQuestionLive({q,people}:any){const count=(o:string)=>people.filter((p:any)=>(Array.isArray(p.pulseResponses[q.id])?p.pulseResponses[q.id]:[p.pulseResponses[q.id]]).includes(o)).length,pct=(o:string)=>people.length?Math.round(count(o)/people.length*100):0,top=q.options.reduce((best:string,o:string)=>count(o)>count(best)?o:best,q.options[0]),topPct=people.length?pct(top):0,category=q.id==='frequency'?'FRECUENCIA DE USO':q.id==='autonomy'?'NIVEL DE AUTONOMÍA CON IA':q.id==='tasks'?'PRINCIPALES USOS DE IA':'SEGURIDAD PERCIBIDA',labels=['Muy inseguro/a','Inseguro/a','Ni seguro/a ni inseguro/a','Seguro/a','Muy seguro/a'];if(q.id==='confidence'){const avg=people.length?people.reduce((n:number,p:any)=>n+Number(p.pulseResponses[q.id]||0),0)/people.length:0,label=avg>=4.5?'Muy seguro/a':avg>=3.5?'Seguridad alta':avg>=2.5?'Seguridad intermedia':avg>=1.5?'Con poca seguridad':'Inseguro/a';return <section className="pulse-question-live confidence-live"><div className="pulse-question-heading"><span>4</span><small>{category}</small><h2>{q.title}</h2></div><div className="confidence-live-grid"><div className="live-highlight security"><small>PROMEDIO DEL GRUPO</small><strong>{avg.toFixed(1)} / 5</strong><b>{label}</b><em>1 = Muy inseguro/a<br/>5 = Muy seguro/a</em></div><div className="vertical-results">{q.options.map((o:string,i:number)=><div key={o}><b style={{height:`${Math.max(8,pct(o)*1.35)}px`}}><i>{pct(o)}%</i></b><span>{o}</span><small>{labels[i]}</small></div>)}</div></div></section>}return <section className="pulse-question-live"><div className="pulse-question-heading"><span>{q.id==='frequency'?'1':q.id==='autonomy'?'2':'3'}</span><small>{category}</small><h2>{q.title}</h2></div><div className="pulse-live-grid"><div className="live-highlight"><strong>{topPct}%</strong><b>{people.length?top:'Sin respuestas todavía'}</b><em>{people.length?'Respuesta más frecuente del grupo':''}</em></div><div className={'compact-options '+(q.id==='tasks'?'many':'')}>{q.options.map((o:string,i:number)=><div key={o}><span>{i+1}</span><b>{o}</b><strong>{pct(o)}%</strong><i><em style={{width:`${pct(o)}%`}}/></i></div>)}</div></div>{q.id==='tasks'&&<p className="multi-note">Selección múltiple: los porcentajes no necesariamente suman 100%.</p>}</section>}


function PulseQuestions({state,qs,people,patch}:any){const step=Math.min(state.pulseFacilitatorStep||0,Math.max(0,qs.length-1)),q=qs[step];return <section className="pulse-question-view"><p className="eyebrow violet">PULSO INICIAL · PREGUNTAS</p><p className="hint">Pregunta {step+1} de {qs.length}</p><PulseQuestionLive q={q} people={people}/><div className="pulse-nav"><button className="secondary" disabled={step===0} onClick={()=>patch((d:any)=>d.pulseFacilitatorStep=step-1,'Pregunta anterior')}>← Anterior</button><button className="primary" disabled={step===qs.length-1} onClick={()=>patch((d:any)=>d.pulseFacilitatorStep=step+1,'Pregunta siguiente')}>Siguiente →</button></div></section>}

function PulseFacilitator({state,current,remain,patch,setPresent}:any){const [confirmReset,setConfirmReset]=useState(false),qs=state.pulseConfig||pulseDefaults,people=state.participants.filter((p:any)=>p.pulseResponses),questions=state.pulseView==='questions',final=!!state.pulseFinal;const reset=()=>{patch((d:any)=>{d.participants.forEach((p:any)=>delete p.pulseResponses);d.pulseFacilitatorStep=0;d.pulseFinal=false;d.pulseView='dashboard';const t=d.momentTimers?.pulse;if(t){t.running=false;t.remainingSeconds=t.initialSeconds;t.hasStarted=false;t.started=0}},'Pulso restablecido');setConfirmReset(false)};const actions=<div className="pulse-actions"><button className="secondary" onClick={()=>patch((d:any)=>d.pulseView=questions?'dashboard':'questions',questions?'Resultados en vivo':'Preguntas del Pulso')}>{questions?'Resultados live':'Ver preguntas'}</button><button className="secondary" onClick={()=>setPresent(true)}><Presentation size={16}/>Modo presentación</button><button className="secondary danger-reset" onClick={()=>setConfirmReset(true)}><RotateCcw size={16}/>Restablecer pulso</button>{!final&&<button className="primary" onClick={()=>patch((d:any)=>{d.pulseFinal=true;d.pulseView='dashboard';if(d.momentTimers?.pulse)d.momentTimers.pulse.running=false},'Pulso finalizado')}>FINALIZAR PULSO</button>}</div>;return <section className="pulse-live"><article className="moment-card pulse-final">{questions?<PulseQuestions state={state} qs={qs} people={people} patch={patch}/>:<PulseDashboard state={state} qs={qs} people={people} final={final}/>}<FacilitatorClock state={state} block={current} remain={remain} patch={patch}/>{actions}{final&&<button className="primary continue" onClick={()=>patch((d:any)=>{d.completed=[...new Set([...d.completed,'pulse'])];const bs=liveBlocks(d),i=bs.findIndex((b:any)=>b.id==='pulse');if(i>=0&&bs[i+1])d.current=bs[i+1].id},'Instruir activado')}>Continuar a Instruir <ChevronRight size={17}/></button>}{confirmReset&&<div className="overlay" role="dialog"><section className="confirm-modal"><p className="eyebrow violet">RESTABLECER PULSO</p><h2>¿Restablecer las respuestas?</h2><p>Esto eliminará las respuestas registradas del Pulso para esta cohorte y devolverá el ejercicio a su estado inicial. Esta acción no se puede deshacer.</p><div><button className="secondary" onClick={()=>setConfirmReset(false)}>Cancelar</button><button className="primary" onClick={reset}>Sí, restablecer</button></div></section></div>}</article></section>}

function ClusterChallenge({o,sourceId,locked,onDragStart}:any){return <article className={`cluster-challenge ${locked?'locked':''}`} draggable={!locked} onDragStart={(e:any)=>!locked&&onDragStart(e,o.id,sourceId)}><small>{o.personName||'Reto enviado'}</small><b>{o.title}</b><p>{o.context||o.problem}</p></article>}
function Wall({state,patch,setView}:any){const [name,setName]=useState(''),[showSource,setShowSource]=useState(false),semantic=(o:any)=>{const text=`${o.title||''} ${o.context||''}`.toLowerCase(),title=o.title||'Reto independiente';if(/hoja de vida|candidato/.test(text))return 'Revisión de hojas de vida';if(/onboarding|ingreso/.test(text))return 'Incorporación de nuevas personas';if(/contenido|redes|campaña/.test(text))return 'Producción de contenido para redes';if(/diseño|pieza gráfica/.test(text))return 'Diseño de piezas gráficas';if(/cartera|pago/.test(text))return 'Seguimiento de cartera';if(/presupuesto|conciliación|finanza/.test(text))return 'Control financiero';if(/informe|consolid/.test(text))return 'Consolidación de informes';if(/inventario/.test(text))return 'Gestión de inventarios';return `Reto independiente · ${title}`},suggest=()=>patch((d:any)=>{const groups:any={};d.opportunities.forEach((o:any)=>{const key=semantic(o);(groups[key]??=[]).push(o)});d.clusters=Object.entries(groups).map(([group,items]:any)=>{const first=items[0],task=(first.context||first.title||'la tarea descrita').replace(/[.]$/,''),friction=(first.friction||'la dificultad descrita').replace(/[.]$/,''),impact=(first.problem||'afecta el resultado esperado').replace(/[.]$/,'');return {id:crypto.randomUUID(),name:group,opportunityIds:items.map((o:any)=>o.id),pov:`Quienes realizan la actividad “${first.title||task}” necesitan ${task} de manera más ágil y consistente porque ${friction}, lo que ${impact}.`,hmw:`¿Cómo podríamos facilitar ${task} de manera que se reduzca este impacto: ${impact}, considerando ${friction}?`,status:'REVISIÓN'}});d.clustersConfirmed=false},'Propuesta automática de IA lista para revisión'),create=()=>{if(!name.trim())return;patch((d:any)=>d.clusters.push({id:crypto.randomUUID(),name,opportunityIds:[],pov:'Por validar con el grupo.',hmw:'¿Cómo podríamos formular esta oportunidad?',status:'REVISIÓN'}),'Clúster creado');setName('')},validated=state.clusters.filter((c:any)=>c.status==='VALIDADO').length,allValidated=state.clusters.length>0&&validated===state.clusters.length,move=(id:string,from:string,to:string)=>patch((d:any)=>{const source=from==='unassigned'?null:d.clusters.find((c:any)=>c.id===from),target=to==='unassigned'?null:d.clusters.find((c:any)=>c.id===to);if((source?.status==='VALIDADO')||(target?.status==='VALIDADO'))return;if(source)source.opportunityIds=source.opportunityIds.filter((x:string)=>x!==id);d.clusters.forEach((c:any)=>{if(c.id!==target?.id)c.opportunityIds=c.opportunityIds.filter((x:string)=>x!==id)});if(target&&!target.opportunityIds.includes(id))target.opportunityIds.push(id)},'Reto reorganizado'),drag=(e:any,id:string,from:string)=>e.dataTransfer.setData('clusterMove',JSON.stringify({id,from})),drop=(e:any,to:string)=>{e.preventDefault();try{const {id,from}=JSON.parse(e.dataTransfer.getData('clusterMove'));move(id,from,to)}catch{}},unassigned=state.opportunities.filter((o:any)=>!state.clusters.some((c:any)=>c.opportunityIds.includes(o.id)));if(showSource)return <div className="page wall"><div className="page-heading"><div><p className="eyebrow violet">AGRUPAR · RETOS ORIGINALES</p><h2>Muro de retos</h2><p>Consulta los aportes originales antes de continuar con la revisión de clústers.</p></div><button className="secondary" onClick={()=>setShowSource(false)}>Agrupar →</button></div><AdminChallengeWall state={state}/></div>;return <div className="page wall"><div className="page-heading"><div><p className="eyebrow violet">AGRUPAR · VALIDACIÓN HUMANA</p><h2>Clústers de retos</h2><p>IA propone por similitud de tarea y dominio; la facilitadora y el grupo revisan, ajustan y validan.</p></div><div className="cluster-progress"><b>Clústers validados · {validated} de {state.clusters.length}</b><small>Propuesta automática generada con IA. Requiere validación humana.</small></div></div><div className="cluster-tools"><button className="secondary" onClick={()=>setShowSource(true)}>← Ver Muro de retos</button><input placeholder="Nombre de nuevo clúster" value={name} onChange={e=>setName(e.target.value)}/><button className="secondary" onClick={create}><Plus size={16}/>Crear clúster</button><button className="primary" onClick={suggest} disabled={!state.opportunities.length}>Agrupar con IA</button></div><section className="cluster-review-grid"><div className="cluster-col unassigned" onDragOver={e=>e.preventDefault()} onDrop={e=>drop(e,'unassigned')}><h3>Sin agrupar <span>{unassigned.length}</span></h3>{unassigned.length?unassigned.map((o:any)=><ClusterChallenge key={o.id} o={o} sourceId="unassigned" locked={false} onDragStart={drag}/>):<p className="empty">Arrastra aquí un reto para retirarlo de una propuesta en revisión.</p>}</div>{state.clusters.map((c:any)=>{const locked=c.status==='VALIDADO',items=state.opportunities.filter((o:any)=>c.opportunityIds.includes(o.id));return <article className={`cluster-review ${locked?'validated':''}`} key={c.id} onDragOver={e=>!locked&&e.preventDefault()} onDrop={e=>!locked&&drop(e,c.id)}><header><input disabled={locked} value={c.name} onChange={e=>patch((d:any)=>d.clusters.find((x:any)=>x.id===c.id).name=e.target.value,'Nombre del clúster actualizado')}/><span>{locked?'✓ Clúster validado':'En revisión'}</span></header><small>{items.length} retos · propuesta automática de IA</small><label>POV · Propuesta IA<textarea disabled={locked} value={c.pov||''} onChange={e=>patch((d:any)=>d.clusters.find((x:any)=>x.id===c.id).pov=e.target.value,'POV actualizado')}/></label><label>Pregunta reto · Propuesta IA<textarea disabled={locked} value={c.hmw||''} onChange={e=>patch((d:any)=>d.clusters.find((x:any)=>x.id===c.id).hmw=e.target.value,'Pregunta reto actualizada')}/></label><div className="cluster-challenges">{items.map((o:any)=><ClusterChallenge key={o.id} o={o} sourceId={c.id} locked={locked} onDragStart={drag}/>)}</div>{locked?<button className="secondary" onClick={()=>patch((d:any)=>{const x=d.clusters.find((x:any)=>x.id===c.id);x.status='REVISIÓN';d.clustersConfirmed=false},'Clúster reabierto')}>Reabrir clúster</button>:<button className="primary" onClick={()=>patch((d:any)=>{const x=d.clusters.find((x:any)=>x.id===c.id);x.status='VALIDADO';d.clustersConfirmed=d.clusters.length>0&&d.clusters.every((z:any)=>z.id===c.id||z.status==='VALIDADO')},'Clúster validado')}>✓ Validar clúster</button>}</article>})}</section><button className="primary continue" disabled={!allValidated} onClick={()=>setView('teams')}>Continuar <ChevronRight size={17}/></button></div>}
function Opportunity({o,clusters,patch}:any){return <article className="opportunity"><small>{o.personName} · {o.radar}</small><b>{o.title}</b><p>{o.problem}</p><select value={clusters.find((c:any)=>c.opportunityIds.includes(o.id))?.id||""} onChange={e=>patch((d:any)=>{d.clusters.forEach((c:any)=>c.opportunityIds=c.opportunityIds.filter((id:string)=>id!==o.id));if(e.target.value)d.clusters.find((c:any)=>c.id===e.target.value).opportunityIds.push(o.id)},"Oportunidad movida")}><option value="">Sin agrupar</option>{clusters.map((c:any)=><option value={c.id} key={c.id}>{c.name}</option>)}</select></article>}

function syncTeams(d:any){const clusters=(d.clusters||[]).filter((c:any)=>c.status==='VALIDADO'),ids=new Set(clusters.map((c:any)=>c.id));d.teams=(d.teams||[]).filter((t:any)=>ids.has(t.clusterId));clusters.forEach((c:any,i:number)=>{if(!d.teams.some((t:any)=>t.clusterId===c.id)){const id=`team_${crypto.randomUUID().replace(/-/g,'').slice(0,16)}`;d.teams.push({id,teamId:id,clusterId:c.id,challengeId:(c.opportunityIds||[])[0]||null,name:`Equipo ${String(i+1).padStart(2,'0')}`,members:[],capacity:Number(d.teamCapacity||5),stage:'Equipo conformado',cardStatus:'not_started',charter:{name:c.name}})}});d.teams.forEach((t:any)=>{t.capacity=Number(t.capacity||d.teamCapacity||5);t.members=t.members||[];if(!t.challengeId)t.challengeId=(clusters.find((c:any)=>c.id===t.clusterId)?.opportunityIds||[])[0]||null;ensureTeamIdentity(t)});d.teamFormationStatus=d.teamFormationStatus||'DRAFT'}
function TeamCard({team,cluster,facilitator=false,patch,state}:any){
  const capacity=Number(team.capacity||5),members=team.members||[],[details,setDetails]=useState(false),[editing,setEditing]=useState(false),[name,setName]=useState(team.name||''),[error,setError]=useState('');
  const save=async()=>{try{setError('');await runOperationalAdmin({executionId:'piloto-gestion-humana'},'admin_upsert',{entity:'team',record:{session_id:team.sheetSessionId,team_id:team.id,name,visible_id:team.visibleId,cluster_id:team.clusterId,challenge_id:team.challengeId,capacity,status:team.stage,participant_ids:members,card_status:team.cardStatus}})}catch(err:any){setError(err?.message||'No fue posible guardar el equipo.')}};
  const remove=async()=>{if(!window.confirm(`¿Eliminar ${team.name} de la base operativa?`))return;try{setError('');await runOperationalAdmin({executionId:'piloto-gestion-humana'},'admin_delete',{entity:'team',id:team.id,session_id:team.sheetSessionId})}catch(err:any){setError(err?.message||'No fue posible eliminar el equipo.')}};
  return <article className="team-formation-card"><small>{team.name.toUpperCase()}</small><b className="team-visible-id">ID {visibleTeamId(team)}</b><h3>{cluster?.name||'Reto por confirmar'}</h3><p className="team-summary-copy">{cluster?.hmw||'La pregunta reto se mostrará cuando el clúster sea validado.'}</p><button className="team-detail-toggle" onClick={()=>setDetails(!details)}>{details?'Ocultar reto':'Ver reto'}</button>{details&&<div className="team-detail"><b>POV</b><p>{cluster?.pov||'POV validado pendiente.'}</p><b>PREGUNTA RETO</b><p>{cluster?.hmw||'Pregunta reto validada pendiente.'}</p></div>}<div className="team-members"><b>Participantes · {members.length} de {capacity}</b>{members.length?members.map((m:any)=><span key={m.email}>{m.name}</span>):<span className="muted">Sin participantes todavía</span>}</div>{facilitator?<><label>Cupos<select value={capacity} onChange={e=>patch((d:any)=>d.teams.find((x:any)=>x.id===team.id).capacity=Number(e.target.value),'Capacidad del equipo actualizada')}>{[2,3,4,5,6,7,8].map(n=><option key={n}>{n}</option>)}</select></label><div className="admin-actions team-admin-actions"><button className="secondary data-action" onClick={()=>setEditing(!editing)}>Editar</button><button className="secondary data-action danger" onClick={remove}>Eliminar</button></div>{editing&&<AdminEditor kind="team" state={state||{participants:[],clusters:[]}} record={{session_id:team.sheetSessionId||state?.executionId,team_id:team.id,name,visible_id:team.visibleId,cluster_id:team.clusterId,challenge_id:team.challengeId,capacity,status:team.stage,participant_ids:members,card_status:team.cardStatus}} onCancel={()=>setEditing(false)} onSave={async(draft:any)=>{try{setError('');await runOperationalAdmin(state||{executionId:'piloto-gestion-humana'},'admin_upsert',{entity:'team',record:draft});setEditing(false)}catch(err:any){setError(err?.message||'No fue posible guardar el equipo.')}}}/>}{error&&<p className="admin-error" role="alert">{error}</p>}</>:<><div className="team-avatars" aria-label={`${members.length} de ${capacity} cupos`}>{Array.from({length:capacity},(_,i)=><i key={i} className={i<members.length?'taken':''}/>)}</div><b className="team-capacity">{members.length} de {capacity} cupos</b></>}<div className="team-progress"><i style={{width:`${Math.min(100,members.length/capacity*100)}%`}}/></div></article>
}
function TeamFacilitator({state,patch}:any){const valid=(state.clusters||[]).filter((c:any)=>c.status==='VALIDADO'),status=state.teamFormationStatus||'DRAFT',teams=(state.teams||[]).filter((t:any)=>valid.some((c:any)=>c.id===t.clusterId)),assigned=teams.reduce((n:number,t:any)=>n+(t.members||[]).length,0),complete=teams.filter((t:any)=>(t.members||[]).length>=Number(t.capacity||5)).length;const prepare=()=>patch((d:any)=>syncTeams(d),'Equipos disponibles desde los clústers validados'),applyAll=()=>patch((d:any)=>{syncTeams(d);d.teams.forEach((t:any)=>t.capacity=Number(d.teamCapacity||5))},'Cupos aplicados a todos los equipos'),open=()=>patch((d:any)=>{syncTeams(d);d.teamFormationStatus='OPEN'},'Conformación de equipos habilitada'),close=()=>patch((d:any)=>d.teamFormationStatus='CLOSED','Conformación de equipos cerrada');return <section className="team-formation"><div className="page-heading"><div><p className="eyebrow violet">MOMENTO 10 · CONFORMAR EQUIPOS</p><h2>{status==='OPEN'?'Equipos en formación.':'Configura los equipos.'}</h2><p>{status==='OPEN'?'Haz seguimiento a la conformación en tiempo real.':'Los equipos se derivan exclusivamente de los clústers ya validados.'}</p></div><div className="team-summary"><b>{status==='OPEN'?`${assigned} participantes`:`${valid.length} clústers disponibles`}</b><small>{status==='OPEN'?`${complete} de ${teams.length} equipos completos`:'Una tarjeta por clúster validado'}</small></div></div>{!valid.length?<div className="empty large">Todavía no hay clústers validados en Agrupar.</div>:<><div className="team-controls"><label>Cupos sugeridos por equipo<select value={state.teamCapacity||5} onChange={e=>patch((d:any)=>d.teamCapacity=Number(e.target.value),'Cupo sugerido actualizado')}>{[2,3,4,5,6,7,8].map(n=><option key={n}>{n}</option>)}</select></label><button className="secondary" disabled={status!=='DRAFT'} onClick={applyAll}>Aplicar a todos</button>{status==='DRAFT'&&<button className="secondary" onClick={prepare}>Actualizar equipos</button>}</div><div className="team-formation-grid">{teams.map((t:any)=>{const cluster=valid.find((c:any)=>c.id===t.clusterId);return <TeamCard key={t.id} team={t} cluster={cluster} facilitator patch={patch} state={state}/>})}</div>{status==='DRAFT'?<button className="primary team-cta" onClick={open}>Habilitar conformación de equipos →</button>:status==='OPEN'?<button className="primary team-cta" onClick={close}>Cerrar conformación de equipos →</button>:<p className="team-closed">✓ Conformación cerrada. Los equipos quedan confirmados para el siguiente momento.</p>}</>}</section>}
function Teams({state,patch}:any){return <div className="page teams"><TeamFacilitator state={state} patch={patch}/></div>}

function Charter({state}:any){return <CharterRepository state={state}/>}
function MemberForm({team,patch}:any){const [n,setN]=useState(""),[e,setE]=useState("");return <form className="member-form" onSubmit={x=>{x.preventDefault();if(!n||!e)return;patch((d:any)=>d.teams.find((t:any)=>t.id===team.id).members.push({name:n,email:e,lead:!team.members.length}),"Integrante agregado");setN("");setE("")}}><input placeholder="Nombre" value={n} onChange={x=>setN(x.target.value)}/><input type="email" placeholder="Correo" value={e} onChange={x=>setE(x.target.value)}/><button className="secondary">Agregar</button></form>}

function Solutions({state,patch}:any){return <div className="page solutions"><p className="eyebrow violet">SOLUCIONES / GALERÍA</p><h2>La siguiente iteración empieza aquí</h2><div className="panel"><h3>Copiloto LAB</h3><p>Configura una URL de GPT cuando esté disponible. El motor mostrará el botón y el QR contextual.</p><label>URL de GPT / copiloto<input placeholder="https://chatgpt.com/g/..." value={state.gptUrl||""} onChange={e=>patch((d:any)=>d.gptUrl=e.target.value,"URL de copiloto guardada")}/></label>{state.gptUrl&&<a className="primary link" target="_blank" href={state.gptUrl}><ExternalLink size={16}/>Abrir Copiloto LAB en ChatGPT</a>}</div><div className="placeholder-grid"><article><span>02</span><h3>Diseñar + construir</h3><p>Sesión bloqueada. La biblioteca permitirá cargar sus bloques sin reconstruir el motor.</p></article><article><span>03</span><h3>Prototipar + humanizar</h3><p>Sesión bloqueada. Estructura preparada para la continuidad metodológica.</p></article></div></div>}

function QRModal({state,onClose,target:targetProp,title}:any){const url=participantUrl(),target=targetProp||state.gptUrl||url;return <div className="overlay" role="dialog"><div className="qr-modal"><button className="close" onClick={onClose}><X/></button><p className="eyebrow violet">{title||"ENTRADA AL LAB"}</p><h2>{title?"Abre este recurso":"Únete desde tu dispositivo"}</h2><img src={`https://api.qrserver.com/v1/create-qr-code/?size=280x280&data=${encodeURIComponent(target)}`} alt="Código QR"/><p>{title?"Escanea el código para abrir el recurso seleccionado.":"Escanea el código para ingresar a la actividad actual."}</p><div className="url-row"><code>{target}</code><button onClick={()=>navigator.clipboard?.writeText(target)}><Copy size={16}/></button></div></div></div>}

function PresentationClock({state,block,remain}:any){const initial=Math.max(1,state.momentTimers?.[block.id]?.initialSeconds||blockSeconds(block)),progress=Math.max(0,Math.min(1,remain/initial)),hero=block.id==='break';return <aside className={'presentation-canonical-clock '+(hero?'break-clock':'')} style={{'--progress':progress} as any}><span>{format(Math.max(0,remain))}</span></aside>}

function PresentationMode({state,current,blocks,index,remain,patch,showQR,setShowQR,onExit,onPrev,onNext}:any){const [wallOpen,setWallOpen]=useState(false),resource=(current.resourceItems||[]).filter((r:any)=>r.active&&r.facilitatorVisible)[0],qs=state.pulseConfig||pulseDefaults,people=state.participants.filter((p:any)=>p.pulseResponses),clockEnabled=!!state.momentTimers?.[current.id]?.enabled;if(current.id==='pulse'){const step=Math.min(state.pulseFacilitatorStep||0,Math.max(0,qs.length-1)),questions=state.pulseView==='questions',goQuestion=(n:number)=>patch((d:any)=>{d.pulseView='questions';d.pulseFacilitatorStep=Math.max(0,Math.min(qs.length-1,n))},'Pregunta de Pulso'),goResults=()=>patch((d:any)=>d.pulseView='dashboard','Resultados en vivo'),advance=()=>patch((d:any)=>{const bs=liveBlocks(d),i=bs.findIndex((b:any)=>b.id==='pulse');if(i>=0&&bs[i+1]){d.completed=[...new Set([...d.completed,'pulse'])];d.current=bs[i+1].id}},'Siguiente momento activo');return <main className="presentation"><button className="presentation-exit" onClick={onExit}>Salir de presentación</button><div className="present-brand">MENTEVIA HUB <small>{state.program||state.name}</small></div>{questions?<article className="presentation-pulse-card"><p className="eyebrow violet">PULSO INICIAL · PREGUNTA {step+1} DE {qs.length}</p><PulseQuestionSummary q={qs[step]} people={people} expanded/></article>:<article className="pulse-dashboard presentation-dashboard"><PulseDashboard state={state} qs={qs} people={people} final={state.pulseFinal}/></article>}{clockEnabled&&<PresentationClock state={state} block={current} remain={remain} patch={patch}/>}<div className="presentation-pulse-nav">{questions?<><button onClick={()=>goQuestion(step-1)} disabled={step===0}>← Anterior</button><button onClick={()=>step<qs.length-1?goQuestion(step+1):goResults()}>Siguiente →</button></>:<><button onClick={()=>goQuestion(qs.length-1)}>← Anterior</button><button onClick={advance}>Siguiente momento →</button></>}</div></main>}if(current.id==='prompt')return <main className="presentation"><button className="presentation-exit" onClick={onExit}>Salir de presentación</button><div className="present-brand">MENTEVIA HUB <small>LAB IA APLICADA</small></div><PromptGuide state={state} patch={patch} advance={onNext}/>{clockEnabled&&<PresentationClock state={state} block={current} remain={remain} patch={patch}/>}</main>;if(current.id==='break')return <main className="presentation"><button className="presentation-exit" onClick={onExit}>Salir de presentación</button><button className="secondary" style={{position:'fixed',top:26,right:210,zIndex:5}} onClick={()=>setShowQR(true)}><QrCode size={16}/>QR de acceso</button><div className="present-brand">MENTEVIA HUB <small>LAB IA APLICADA</small></div><div className="present-count">SESIÓN 01 · {String(index+1).padStart(2,'0')}/{String(blocks.length).padStart(2,'0')}</div><article><p>MOMENTO {String(index+1).padStart(2,'0')} · {current.phase}</p><h1>{current.name}</h1><span className="present-line"/><h2>{current.purpose}</h2><div className="present-content">{current.content}</div>{clockEnabled&&<PresentationClock state={state} block={current} remain={remain}/>}<div className="present-bottom"><div><button onClick={onPrev} disabled={index===0}><ChevronLeft/></button><button onClick={onNext} disabled={index===blocks.length-1}><ChevronRight/></button></div></div></article>{showQR&&<QRModal state={state} onClose={()=>setShowQR(false)}/>}</main>;if(current.id==='group'&&wallOpen)return <main className="presentation"><button className="presentation-exit" onClick={onExit}>Salir de presentación</button><div className="present-brand">MENTEVIA HUB <small>LAB IA APLICADA</small></div><article><p className="eyebrow violet">MOMENTO 09 · AGRUPAR · MURO DE RETOS</p><h1>Retos del grupo</h1><p className="present-content">Consulta los aportes recibidos sin abandonar la presentación.</p><ChallengeWall state={state}/><div className="present-bottom"><button className="secondary" onClick={()=>setWallOpen(false)}>← Volver a Agrupar</button></div></article></main>;if(current.id==='land')return <main className="presentation reto-presentation-shell"><button className="presentation-exit" onClick={onExit}>Salir de presentación</button><div className="present-brand">MENTEVIA HUB <small>LAB IA APLICADA</small></div><div className="present-count">SESIÓN 01 · {String(index+1).padStart(2,'0')}/{String(blocks.length).padStart(2,'0')}</div><RetoPresentation state={state} patch={patch} onNext={onNext}/>{clockEnabled&&<PresentationClock state={state} block={current} remain={remain} patch={patch}/>}</main>;return <main className="presentation"><button className="presentation-exit" onClick={onExit}>Salir de presentación</button><div className="present-brand">MENTEVIA HUB <small>LAB IA APLICADA</small></div><div className="present-count">SESIÓN 01 · {String(index+1).padStart(2,'0')}/{String(blocks.length).padStart(2,'0')}</div><article><p>MOMENTO {String(index+1).padStart(2,'0')} · {current.phase}</p><h1>{current.name}</h1><span className="present-line"/><h2>{current.purpose}</h2>{resource?<ResourceViewer resource={resource}/>:<div className="present-content">{current.content}</div>}{current.id==='group'&&<button className="secondary" onClick={()=>setWallOpen(true)}>← Ver Muro de retos</button>}<div className="present-bottom">{clockEnabled&&<PresentationClock state={state} block={current} remain={remain}/>}<button onClick={()=>setShowQR(true)}><QrCode/>Mostrar QR</button><div><button onClick={onPrev} disabled={index===0}><ChevronLeft/></button><button onClick={onNext} disabled={index===blocks.length-1}><ChevronRight/></button></div></div></article>{showQR&&<QRModal state={state} target={resource?.generateQR?resource.url:undefined} title={resource?.generateQR?'RECURSO DEL BLOQUE':undefined} onClose={()=>setShowQR(false)}/>}</main>}

function ParticipantResourceDock({current}:any){const interactive=['concepts','explore'].includes(current?.id),resources=(current?.resourceItems||[]).filter((r:any)=>r.active&&(r.participantVisible||(interactive&&r.facilitatorVisible)));if(!interactive&&!resources.length)return null;return <aside className="participant-resources">{resources.length>0&&<><small>EXPERIENCIA DE ESTA ACTIVIDAD</small>{resources.map((r:any)=><section className="participant-experience" key={r.id}><b>{r.name}</b>{r.description&&<p>{r.description}</p>}{interactive||r.type==='HTML_WEB'?<a className="primary link" href={r.url} target="_blank" rel="noreferrer"><ExternalLink size={16}/>Abrir experiencia ↗</a>:r.viewMode==='EMBEBIDO'?<ResourceViewer resource={r} compact/>:<a className="primary link" href={r.url} target="_blank" rel="noreferrer"><ExternalLink size={16}/>{r.name}</a>}</section>)}</>}{current?.methodology&&<div className="participant-method"><small>METODOLOGÍA</small><p>{current.methodology}</p></div>}</aside>}

function Participant({state,current,commit,teamAction,pulseClockRemain,momentClockRemain}:any){const [identity,setIdentity]=useState<any>(null),[name,setName]=useState(""),[email,setEmail]=useState(""),[company,setCompany]=useState(""),[sent,setSent]=useState(""),[shown,setShown]=useState(current?.id);useEffect(()=>{const saved=sessionStorage.getItem("lab-participant");if(saved)setIdentity(JSON.parse(saved))},[]);useEffect(()=>{if(current?.id)setShown(current.id)},[current?.id]);async function save(mut:(d:any)=>void,msg:string){const d=structuredClone(state);mut(d);const ok=await commit(d,msg);setSent(ok?msg:"No se pudo registrar. Inténtalo de nuevo.");return ok}if(state.sessions[0].status!=="ABIERTA")return <main className="participant blocked"><span className="mark">M</span><p className="eyebrow violet">LAB IA APLICADA</p><h1>La sesión todavía no está abierta.</h1><p>Espera a que la facilitadora habilite el ingreso.</p></main>;if(!identity)return <main className="participant"><ParticipantBrand/><section className="participant-card"><p className="eyebrow violet">SESIÓN 01 ABIERTA</p><h1>Bienvenida al LAB</h1><p>Registra tus datos una sola vez para entrar al recorrido.</p><form onSubmit={async e=>{e.preventDefault();const person={id:crypto.randomUUID(),name,email,company};if(await save((d:any)=>d.participants.some((p:any)=>p.email===email)||d.participants.push(person),"Registro completado")){sessionStorage.setItem("lab-participant",JSON.stringify(person));setIdentity(person)}}}><label>Nombre<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>Correo<input required type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Empresa / organización<input required value={company} onChange={e=>setCompany(e.target.value)}/></label><button className="primary">Entrar a la sesión</button></form></section></main>;const person=state.participants.find((p:any)=>p.email===identity.email)||identity;const visible=state.blocks.filter((b:any)=>b.id!=='charter'&&(state.completed.includes(b.id)||b.id===current?.id));const shownBlock=visible.find((b:any)=>b.id===shown)||current;return <main className="participant"><ParticipantBrand/><header className="participant-top"><div><small>SESIÓN 01 · MOMENTO ACTIVO</small><h1>{shownBlock?.id==='land'?'Tarjetas Reto':shownBlock?.name}</h1></div><span className="live-pill">{shownBlock?.id===current?.id?"EN VIVO":"RECORRIDO"}</span></header><nav className="participant-history">{visible.map((b:any)=><button key={b.id} onClick={()=>setShown(b.id)}>{b.id==='land'?'Tarjetas Reto':b.name}</button>)}</nav><section className="participant-activity">{shownBlock?.id==='land'?<RetoGuide state={state} patch={(mut:any,msg:string)=>save(mut,msg)} person={person}/>:shownBlock?.id==='prompt'?<PromptGuide state={state} patch={()=>{}} readOnly/>:shownBlock?.id==='instruct'?<InstructGuide state={state} patch={()=>{}} readOnly/>:<><p className="eyebrow violet">{shownBlock?.phase}</p><h2>{shownBlock?.purpose}</h2><p>{shownBlock?.content}</p>{shownBlock?.id==="pulse"?<Pulse state={state} person={person} save={save} sent={sent} pulseClockRemain={pulseClockRemain}/>:shownBlock?.id==="observe"?<OpportunityForm state={state} person={person} save={save} sent={sent}/>:shownBlock?.id==="group"?<ParticipantClusterWall state={state}/>:shownBlock?.id==="team"?<JoinTeam state={state} person={person} teamAction={teamAction}/>:<><p className="wait-note">Sigue la consigna en pantalla. Esta actividad no requiere un registro digital adicional.</p>{state.gptUrl&&<a className="primary link" target="_blank" href={state.gptUrl}><ExternalLink size={16}/>Abrir asistente del LAB</a>}</>}</>}</section>{shownBlock?.id==='break'&&state.momentTimers?.break?.enabled&&<ParticipantMomentClock state={state} current={shownBlock} remain={momentClockRemain}/>}<ParticipantResourceDock current={shownBlock}/>{shownBlock?.id==="pulse"&&state.momentTimers?.pulse?.enabled&&<div className="participant-clock"><Clock3 size={16}/>{format(pulseClockRemain)}</div>}{state.helpEnabled&&<button className="help-button" onClick={()=>save((d:any)=>d.help.push({id:crypto.randomUUID(),name:person.name,status:"PENDIENTE",moment:shownBlock?.name,reason:"Solicitud desde actividad: "+shownBlock?.name}),"Solicitud enviada")}>¿Necesitas ayuda? · PEDIR AYUDA</button>}{sent&&<p className="participant-sent">{sent}</p>}</main>}
function ParticipantBrand(){return <div className="participant-brand"><span className="mark">M</span><div><b>MENTEVIA HUB</b><small>LAB IA APLICADA</small></div></div>}
function ParticipantSocializar({state,current}:any){const teams=(state.teams||[]).filter((team:any)=>Object.keys(team.charter||{}).length>0),selected=teams.find((team:any)=>team.id===(state.sharePresentedTeamId||state.shareSelectedTeamId))||teams[0],[expanded,setExpanded]=useState(false),enabled=!!state.momentTimers?.share?.enabled,remain=clockFor(state,state.blocks.find((b:any)=>b.id==='share'),Date.now()),initial=Math.max(1,state.momentTimers?.share?.initialSeconds||90),progress=Math.max(0,Math.min(1,remain/initial));return <main className="participant participant-socializar"><ParticipantBrand/><header className="participant-top"><div><small>SESIÓN 01 · MOMENTO ACTIVO</small><h1>Socializar</h1></div><span className="live-pill">EN VIVO</span></header><section className={'participant-activity participant-share-sheet '+(enabled?'clock-open':'')}><div><p className="eyebrow violet">MOMENTO 12 · SOCIALIZAR</p><RetoFicha state={state} team={selected} expanded={expanded} onToggle={()=>setExpanded(!expanded)}/></div>{enabled&&<aside className="participant-share-clock" style={{'--progress':progress} as any}><span>{format(Math.max(0,remain))}</span></aside>}</section></main>}
function ParticipantEnhanced(props:any){const joined=typeof window!=='undefined'&&!!sessionStorage.getItem('lab-participant');return props.current?.id==='share'&&joined?<ParticipantSocializar state={props.state} current={props.current}/>:<Participant {...props}/>}
function ParticipantMomentClock({state,current,remain}:any){if(current?.id==='share'||!state.momentTimers?.[current?.id]?.enabled)return null;const initial=Math.max(1,state.momentTimers?.[current.id]?.initialSeconds||blockSeconds(current)),progress=Math.max(0,Math.min(1,remain/initial));return <aside className={'participant-moment-clock '+(current?.id==='break'?'break-clock':'')} style={{'--progress':progress} as any}><span>{format(Math.max(0,remain))}</span></aside>}
function Pulse({state,person,save}:any){const qs=state.pulseConfig||pulseDefaults,people=state.participants.filter((p:any)=>p.pulseResponses),stored=state.participants.find((p:any)=>p.email===person.email)?.pulseResponses;const [answers,setAnswers]=useState<any>(stored||{}),[step,setStep]=useState(0),[saving,setSaving]=useState(false),[failed,setFailed]=useState(false);const q=qs[step];if(stored||state.pulseFinal)return <div className="participant-pulse-results"><div className="pulse-complete"><b>{state.pulseFinal?'PULSO FINALIZADO':'✓ TU RESPUESTA FUE REGISTRADA'}</b><p>{state.pulseFinal?'Así llegó este grupo.':'Así llega este grupo.'}</p></div><PulseDashboard state={state} qs={qs} people={people} final={state.pulseFinal}/></div>;const choose=(v:string)=>setAnswers((a:any)=>q.kind==='multi'?{...a,[q.id]:(a[q.id]||[]).includes(v)?a[q.id].filter((x:string)=>x!==v):[...(a[q.id]||[]),v]}:{...a,[q.id]:v});const valid=q?.kind==='multi'?(answers[q.id]||[]).length>0:!!answers[q?.id];const finish=async()=>{setSaving(true);setFailed(false);const ok=await save((d:any)=>d.participants.find((p:any)=>p.email===person.email).pulseResponses=answers,'Pulso registrado');setSaving(false);setFailed(!ok)};return <div className="activity-form pulse-form"><p className="eyebrow violet">PULSO INICIAL</p><h3>Reconocer nuestro punto de partida</h3><p className="hint">Pregunta {step+1} de {qs.length}</p><h4>{q?.title}</h4><div className={q?.kind==='scale'?'scale pulse-options':'pulse-options'}>{q?.options.map((o:string)=><button type="button" className={(q.kind==='multi'?(answers[q.id]||[]).includes(o):answers[q.id]===o)?'picked':''} key={o} onClick={()=>choose(o)}>{o}</button>)}</div>{q?.kind==='scale'&&<div className="scale-labels"><span>1 = Inseguro/a</span><span>5 = Muy seguro/a</span></div>}{q?.kind==='multi'&&(answers[q.id]||[]).includes('Otra')&&<input placeholder="Escribe cuál" value={answers[q.id+'Other']||''} onChange={e=>setAnswers({...answers,[q.id+'Other']:e.target.value})}/>}<div className="pulse-nav"><button className="secondary" disabled={step===0} onClick={()=>setStep(step-1)}>← Anterior</button>{step<qs.length-1?<button className="primary" disabled={!valid} onClick={()=>setStep(step+1)}>Siguiente →</button>:<button className="primary" disabled={!valid||saving} onClick={finish}>{saving?'Enviando…':'ENVIAR PULSO'}</button>}</div>{failed&&<p className="error">No se pudo registrar. Reintenta el envío.</p>}</div>}
function OpportunityForm({state,person,save}:any){const steps=state.observeConfig||observeDefaults,step=Math.max(0,Math.min(steps.length-1,state.observeStep||0)),item=steps[step],current=state.opportunities.find((o:any)=>o.email===person.email),key=`lab-observe-draft-${person.email}`,stored=typeof window==='undefined'?null:sessionStorage.getItem(key),[data,setDataState]=useState<any>(current||(stored?JSON.parse(stored):{radar:'',title:'',problem:'',context:'',friction:''})),[saving,setSaving]=useState(false),setData=(next:any)=>{setDataState(next);sessionStorage.setItem(key,JSON.stringify(next))};if(item.id!=='reframe'&&item.id!=='register')return <div className="activity-form"><p className="eyebrow violet">MOMENTO 08 · OBSERVAR · {String(step+1).padStart(2,'0')} · {item.name.toUpperCase()}</p><h3>{item.title}</h3><p>{item.content}</p><ObserveContent item={item} state={state} audience="participant"/></div>;const valid=!!(data.title&&data.context&&data.friction&&data.problem),send=async()=>{if(!valid||saving)return;setSaving(true);const ok=await save((d:any)=>{const old=d.opportunities.find((o:any)=>o.email===person.email);const rec={...data,id:old?.id||crypto.randomUUID(),email:person.email,personName:person.name,createdAt:old?.createdAt||Date.now()};if(old)Object.assign(old,rec);else d.opportunities.push(rec)},'Tu reto fue enviado al muro');if(ok)sessionStorage.removeItem(key);setSaving(false)};return <div className="activity-form challenge-work"><p className="eyebrow violet">MOMENTO 08 · OBSERVAR · {String(step+1).padStart(2,'0')} · {item.name.toUpperCase()}</p><h3>{item.title}</h3><p>{item.id==='reframe'?'Con la información que recopilaste, completa los campos para transformar la situación en un reto.':'Compártelo con el grupo y observa cómo se construye el muro en tiempo real.'}</p><div className="challenge-work-grid"><section><ChallengeFields data={data} setData={setData}/></section><section><b>{item.id==='reframe'?'Vista previa de tu tarjeta':'Tu reto'}</b><ChallengeCard data={data} preview/></section></div>{item.id==='register'&&<><div className="register-participant-reference"><section><b>Ejemplo de tarjeta de reto</b><ChallengeCard data={challengeExample}/></section></div><button className="primary" disabled={!valid||saving} onClick={send}>{saving?'Enviando…':'Enviar al muro'}</button><ChallengeWall state={state} audience="participant"/></>}</div>}
function JoinTeam({state,person,teamAction}:any){const status=state.teamFormationStatus||'DRAFT',valid=(state.clusters||[]).filter((c:any)=>c.status==='VALIDADO'),teams=(state.teams||[]).filter((t:any)=>valid.some((c:any)=>c.id===t.clusterId)),mine=teams.find((t:any)=>(t.members||[]).some((m:any)=>m.email===person.email));if(status==='DRAFT')return <p className="wait-note">La facilitadora habilitará la elección de equipos en breve.</p>;return <div className="join-team"><p>{status==='OPEN'?'Explora los retos definidos y únete al equipo cuya oportunidad te interese desarrollar.':'La conformación terminó. Estos son los equipos confirmados.'}</p><div className="team-formation-grid participant-teams">{teams.map((team:any)=>{const cluster=valid.find((c:any)=>c.id===team.clusterId),full=(team.members||[]).length>=Number(team.capacity||5),isMine=mine?.id===team.id;return <div key={team.id} className={isMine?'my-team':''}><TeamCard team={team} cluster={cluster}/>{status==='OPEN'&&(isMine?<button className="secondary" onClick={()=>teamAction('leave',team.id,person)}>Abandonar equipo</button>:<button className="primary" disabled={full} onClick={()=>teamAction('join',team.id,person)}>{full?'Equipo completo':mine?'Cambiar a este equipo':'Unirme a este equipo'}</button>)}{isMine&&<b className="your-team">✓ Tu equipo</b>}</div>})}</div></div>}
function InstructGuide({state,patch,readOnly=false,advance}:any){
  const names=['Construyan la instrucción','Probemos las instrucciones','Evaluemos lo ocurrido'];
  const step=Math.max(0,Math.min(2,state.instructStep||0));
  const go=(n:number)=>!readOnly&&patch((d:any)=>d.instructStep=Math.max(0,Math.min(2,n)),'Subsección de Instruir actualizada');
  return <section className="instruct-guide">
    <div className="reto-tabs">{names.map((x,i)=><button key={x} className={i===step?'active':''} disabled={readOnly} onClick={()=>go(i)}><span>{i+1}</span>{x}</button>)}</div>
    <p className="eyebrow violet">MOMENTO 03 · INSTRUIR · {String(step+1).padStart(2,'0')}</p>
    <h1>{names[step]}</h1>
    {step===0?<><p className="instruct-lead">En equipo, construyan instrucciones para una tarea que la facilitadora indicará durante la actividad.</p><article className="instruct-card"><b>PROPÓSITO</b><p>Escriban la instrucción tal como la darían a una persona para resolver la tarea. Decidan qué información es necesaria y qué detalles deben quedar explícitos.</p></article><p className="instruct-time">◷ Tiempo sugerido · <b>10 minutos</b></p></>:step===1?<><p className="instruct-lead">Probemos las instrucciones que construyeron los equipos y observemos qué ocurre cuando se ejecutan tal como fueron escritas.</p><article className="instruct-card"><b>DINÁMICA</b><p>Un equipo comparte su instrucción. Otro equipo la ejecuta literalmente, sin completar vacíos ni asumir información que no esté escrita.</p></article><p className="instruct-time">◷ Tiempo sugerido · <b>10 minutos</b></p></>:<><p className="instruct-lead">Evaluemos lo ocurrido y conectemos la experiencia con los principios de una instrucción clara.</p><article className="instruct-card"><b>PREGUNTAS PARA LA REFLEXIÓN</b><ul><li>¿Qué ocurrió?</li><li>¿El resultado era el esperado?</li><li>¿Qué tuvo que interpretar o asumir quien recibió la instrucción?</li><li>¿Qué información hizo falta?</li><li>¿Qué cambiaríamos en la instrucción?</li></ul></article><article className="instruct-card"><b>CONCEPTO CLAVE</b><p>Una instrucción se interpreta a partir de la información explícita que contiene y del contexto disponible. Cuando faltan claridad, contexto o detalles relevantes, diferentes personas pueden interpretarla de manera distinta y producir resultados diferentes.</p><small>Referencia: Project Zero, Harvard Graduate School of Education · Visible Thinking.</small></article><article className="instruct-card"><b>METODOLOGÍA DEL EJERCICIO</b><p><strong>Aprendizaje experiencial (Learning by Doing).</strong> Primero hacemos, luego observamos lo que ocurrió y finalmente conectamos la experiencia con conceptos y buenas prácticas para mejorar las instrucciones.</p></article></>}
    {!readOnly&&<div className="reto-nav"><button className="secondary" disabled={step===0} onClick={()=>go(step-1)}>← Anterior</button>{step===2?<button className="primary" disabled={!advance} onClick={advance}>Siguiente momento →</button>:<button className="primary" onClick={()=>go(step+1)}>Siguiente →</button>}</div>}
  </section>
}
